(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lv"] = {"ui":{"skip":"Pāriet uz saturu","back":"← Atpakaļ uz AI-gile","lang.button":"Valoda: {name}","lang.dialog":"Izvēlies valodu","lang.search":"Meklēt valodas","lang.none":"Neviena valoda neatbilst","lang.notYet":"{name} vēl nav iztulkota","theme.aria":"Pārslēgt tēmu: gaiša, tumša vai melna","theme.toLight":"Pārslēgt uz gaišo tēmu","theme.toDark":"Pārslēgt uz tumšo tēmu","theme.toBlack":"Pārslēgt uz melno tēmu (īsti melna, saudzīga OLED ekrāniem)","words.underline":"Pasvītrot šos vārdus lapā","words.underlineHelp":"Novieto kursoru uz vārda ar punktētu pasvītrojumu vai pieskaries tam, lai redzētu, ko tas nozīmē.","words.col.todo":"Šobrīd izvēlētās kartītes: komanda tām ķersies klāt nākamajām.","words.col.doing":"MI šobrīd strādā pie šīs kartītes.","words.col.review":"Viens MI darbu paveicis; cits to pārbauda, pirms tas nonāk pie tevis.","words.col.verify":"Gaida tevi: pamēģini un pasaki, vai strādā.","words.col.team":"Tavas piezīmes vai atbildes, kas gaida, kad komanda tās pacels.","words.col.done":"Pabeigts un pieņemts.","index.title":"AI-gile: tava MI izstrādes komanda vienā tāfelē","index.description":"AI-gile ir kanban tāfele MI programmēšanas komandām. Tās strādā, kamēr tu guli; tev paliek viena īsa kaudzīte: ko izlemt, ko pārbaudīt un ko pieņemt.","hero.logoAlt":"AI-gile tāfeles ikona","hero.h1.html":"Tava MI izstrādes komanda vienā&nbsp;tāfelē.","hero.alpha":"🐣 Slēgta pirmsalfa","hero.alphaTitle":"Agrīna un nepabeigta: paldies, ka izmēģini!","hero.lede":"Viņi būvē, kamēr tu guli. Pamodies tu atrodi vienu īsu kaudzīti: pāris jautājumu, pāris lietu, ko pārbaudīt, un viens otrs violets dimants. Uzklikšķini, pieņem un atpakaļ pie kafijas.","dl.windows":"Windows lietotne","dl.browser":"Palaid pārlūkā","dl.messenger":"📱 Messenger tavam telefonam","dl.soon":"Drīzumā","dl.notify":"🔔 Pastāsti, kad atvērsies","dl.notifySmall":"Alfa vai beta","hero.secondary":"Agile, bet komandai nekad nevajag stāvošo rīta kafiju. (Stand-up viņi tāpat rīko.)","pitch.h2":"AI-gile tik vārdos, cik vēlies","pitch.lede":"Izvēlies garumu, no viena vārda līdz 144. Katrs garums ir savs apraksts, uzrakstīts tieši tam. Velc slīdni vai lieto bulttaustiņus.","pitch.rangeLabel":"Garums vārdos","pitch.dice":"🎲 cita versija","pitch.words.one":"{n} vārds","pitch.words.other":"{n} vārdi","pitch.letters.one":"{n} burts","pitch.letters.other":"{n} burti","pitch.chars.one":"{n} rakstzīme","pitch.chars.other":"{n} rakstzīmes","count.line.html.one":"Tāfelē šobrīd ir {n} kartīte","count.line.html.other":"Tāfelē šobrīd ir {n} kartītes","people.humans.html.one":"👥 {n} cilvēks","people.humans.html.other":"👥 {n} cilvēki","people.agents.html.one":"🤖 {n} aģents","people.agents.html.other":"🤖 {n} aģenti","people.working.html.one":"⚡ {n} šobrīd strādā","people.working.html.other":"⚡ {n} šobrīd strādā","pre.title":"AI-gile: šeit kaut kas top","pre.description":"Šeit kaut kas top: tāfele, kurā MI komandas būvē to, ko tu palūdz, un pa ceļam tevi māca. Pagaidām slēgta pirmsalfa ar draugiem.","pre.h1":"Šeit kaut kas top. 🤫","pre.line":"Tāfele, kurā MI komandas būvē to, ko tu palūdz, un pa ceļam tevi māca. Pagaidām slēgta pirmsalfa ar draugiem.","pre.btn":"🔔 Pastāsti, kad atvērsies","pre.peek":"Aiz stikla: īstā tāfele, tiešraidē. Katra kartīte ir krāsaina svītra.","pre.peekFake":"Aiz stikla: tā izskatās tāfele darbā.","pre.night":"🌙 Nakts sargs ir pie stūres · 😴 cilvēks atpūšas","features.aria":"Ko tā dara","f.pile.h":"Viena kaudzīte tev","f.pile.html":"<b>Tev</b> satur visu, kas gaida tevi, no visiem projektiem: jautājumus, lietas, ko pārbaudīt, un uzdevumus, ko var izdarīt tikai cilvēks. Tava rinda parāda, kas ir nākamais un cik tas aizņems.","f.sleep.h":"Komandas, kas strādā, kamēr tu guli","f.sleep.p":"Katram projektam ir līderis un MI aģentu komanda. Komentē kartīti, un komanda pamostas, paveic darbu un atdod to atpakaļ ar soļiem, kurus var izpildīt arī nogurusi cilvēks.","f.tester.h":"Vispirms pārbauda MI testētājs","f.tester.p":"Pirms kaut kas nonāk pie tevis, testētājs izpilda soļus lietotnes kopijā un parāda redzēto ar ekrānuzņēmumu. Pārlapo izturējušos un pieņem ar vienu klikšķi.","f.proof.h":"Pierādījumi, nevis solījumi","f.proof.p":"Katra nodošana parāda, kas mainījies: failus, atšķirības, ekrānuzņēmumus. Nav jāatver katra lietotne, lai redzētu, vai viss gatavs.","f.chat.h":"Tērzē ar saviem līderiem","f.chat.p":"Discord stila josla: viena ikona katram projektam, violeti dimanti tam, kam vajag tevi. Uzraksti līderim ideju; viņš to pārvērš kartītēs un plānā ar pogu ✅ Aiziet.","f.tidy.h":"Pati uztur kārtību","f.tidy.p":"Saistītās kartītes saplūst vienā, juceklīgi nosaukumi tiek sakārtoti, un tokenu pārbaude uztur kodu kompaktu. Mazāk, starp ko pārslēgties, mazāk, par ko domāt.","f.private.h":"Tava, tavā datorā","f.private.li1":"Tāfele darbojas tavā paša datorā un atbild tikai tev.","f.private.li2":"Privātās ziņas starp cilvēkiem ir šifrētas no gala līdz galam.","f.private.li3":"Nekādu kontu, izsekotāju un sīkdatņu.","f.lang.h":"Tavā valodā","f.lang.p":"Vairāk nekā 120 valodu, no holandiešu, velsiešu un japāņu līdz pirātu, Jodas un klingonu valodai, ar ātru pārslēgšanos atpakaļ uz angļu valodu nozares žargonam.","f.service.h":"No idejas līdz īstam pakalpojumam","f.service.p":"Ar MI uzbūvēji kaut ko, ko cilvēki tagad lieto? Atzīmē to kā pakalpojumu, un dēlis palīdz to labi uzturēt: pieejamības pārbaudes, publiska statusa lapa, incidenti ar pēcanalīzi, izmaiņas, kurām vajag Go, dublējumi, ko pārbauda katru dienu. Palīdzība māca katru soli pa ceļam.","msgr.h2":"AI-gile Messenger: tava komanda kabatā","msgr.p1":"Runā ar savu MI komandu, neatverot dēli. Tērzē ar projektu vadītājiem un draugiem, skaties kartītes testa soļus un atbildi uz tiem, viss no tava telefona.","msgr.p2":"Lai savienotu pārī, noskenē QR kodu savā dēlī. Pirmā reize? Draudzīga demo tērzēšana visu parādīs.","msgr.when":"Vispirms Android, pēc tam tīmekļa versija telefoniem un iPhone.","msgr.who":"Tavs projekta vadītājs","msgr.b1":"Tumšā režīma labojums ir gatavs. Atsūtīt testa soļus?","msgr.b2":"Jā, lūdzu!","msgr.b3":"1. Atver Iestatījumus. 2. Izvēlies Tumšo. Vai izskatās pareizi?","tl.aria":"Laika līnija no pirmās sarunas līdz ceļvedim","tl.h2":"No pirmās sarunas līdz tam, kas sekos","tl.lede":"Īsti datumi un laiki tavā laika joslā. Pēc šodienas tas ir plāns, bez solītiem datumiem.","tl.today":"Šodien","tl.planned":"plānots","tl.doing":"procesā","tl.cards.one":"{n} kartīte","tl.cards.other":"{n} kartītes","join.h2":"Pievienojies","join.lede":"AI-gile veido bārdains dīvainis ar AuDHD un dažām cīņām ar mentālo veselību, un liels pulks pacietīgu aģentu. Pagaidām tā ir privāta, slēgtā alfā kopā ar draugiem. Vai gribi izmēģināt, kad tā atvērsies?","join.btn":"Pieteikt interesi","join.small":"Mēs uzrakstīsim e-pastu un neko citu","footer.tag":"AI-gile. Nekādu izsekotāju, nekādu sīkdatņu, nekādas stāvošās rīta kafijas.","footer.licence":"Biznesa licence","footer.status":"Statuss","footer.privacy":"Ko mēs glabājam","footer.thanks":"Zvani, pateicoties ChilledChat","form.sending":"Sūta…","form.failed":"Neizdevās: mēģini vēlāk vēlreiz.","form.offline":"Neizdevās sazināties ar AI-gile: mēģini vēlāk vēlreiz.","form.keep":"Mēs to izmantojam tikai, lai tev atbildētu, un pēc tam izdzēšam. Nekādu izsekotāju, nekādu sīkdatņu.","form.keepLink":"Ko mēs glabājam","interest.title":"AI-gile: pastāsti, kad atvērsies alfa","interest.description":"Atstāj savu e-pastu, lai uzzinātu, kad atvērsies AI-gile slēgtā alfa vai beta.","interest.h1":"🔔 Pastāsti, kad atvērsies","interest.lede":"AI-gile ir slēgtā pirmsalfā. Atstāj e-pastu, un mēs uzrakstīsim vienreiz, kad tev būs vieta.","interest.email":"Tavs e-pasts","interest.which":"Kuru testu?","interest.alpha":"Slēgtā alfa: agrīna, raupja, daudz izmaiņu","interest.beta":"Beta: stabilāka, vēlāk","interest.both":"Jebkuru, kas būs pirmā","interest.submit":"Pieraksti mani sarakstā","interest.thanks":"Paldies! Tu esi sarakstā.","licence.title":"AI-gile: biznesa licence","licence.description":"Lieto AI-gile savā uzņēmumā? Pieprasi bezmaksas biznesa licenci.","licence.h1":"📜 Biznesa licence","licence.lede":"Lieto AI-gile darbā? Pastāsti, kas tu esi un ar ko nodarbojies. Ja tas nes kādu labumu, licence ir bez maksas.","licence.company":"Uzņēmums","licence.website":"Tīmekļa vietne","licence.what":"Ar ko nodarbojies","licence.how":"Kā tas palīdz pasaulei","licence.email":"E-pasts","licence.submit":"Pieteikties","licence.thanks":"Paldies! Atbildēsim pa e-pastu.","status.title":"AI-gile statuss","status.h1":"AI-gile statuss","status.quiet":"Viss mierīgi","status.intro":"Vai AI-gile šobrīd darbojas? Šī lapa ik pēc 5 minūtēm pārbauda vietni, tāfeļu koplietošanu, zvanus un lejupielādi.","status.up":"Darbojas (atbildēja {ms} ms laikā)","status.slow":"Neatbildēja uz pēdējo pārbaudi, mēģina vēlreiz","status.down":"Nedarbojas: neatbildēja uz pēdējām divām pārbaudēm","status.svc.web":"Vietne","status.svc.web.offers":"Šī vietne: kas ir AI-gile, un interešu pieteikuma veidlapa","status.svc.boards":"Tāfeļu koplietošana","status.svc.boards.offers":"Publiskas tāfeles, ziņas starp draugiem un ielūgumi","status.svc.calls":"Zvani","status.svc.calls.offers":"Balss, video un ekrāna kopīgošana AI-gile","status.svc.download":"Lejupielāde","status.svc.download.offers":"Windows instalētājs un ielūgumu saites","status.checking":"Pārbauda…","status.offline":"Šobrīd nevar sazināties ar statusa pakalpojumu (mēģina vēlreiz)","status.updated":"atjaunināts {ago}","status.justNow":"tikko","status.min":"pirms {n} min","status.hours":"pirms {n} h","status.days":"pirms {n} d","privacy.title":"AI-gile: ko mēs glabājam","privacy.h1":"Ko mēs glabājam","privacy.lede":"Īsumā: tikai to, ko tu mums nosūti, un ne ilgi.","privacy.only":"Tikai to, ko tu mums nosūti: to, ko ieraksti veidlapā, piemēram, savu e-pastu. Neko citu par tevi.","privacy.sealed":"Tas tiek aizzīmogots, lai mūsu serveris to nevarētu izlasīt: jau tavā pārlūkā, pirms tas tiek nosūtīts (vecākā pārlūkā tajā brīdī, kad tas pienāk). Atvērt to var tikai mūsu pašu tāfele.","privacy.server":"No servera tas tiek izdzēsts, tiklīdz nonāk mūsu tāfelē. Viss, kas tur vēl ir pēc 30 dienām, tiek izdzēsts jebkurā gadījumā.","privacy.board":"Mūsu tāfelē mēs to glabājam tikai līdz brīdim, kad esam tev atbildējuši, un tad izdzēšam arī tur.","privacy.none":"Nekādu izsekotāju, nekādu sīkdatņu, nekādas analītikas.","privacy.local":"Tava valoda un gaišās vai tumšās tēmas izvēle paliek tavā pārlūkā. Tās nekad netiek sūtītas mums.","privacy.ask":"Gribi, lai to izdzēšam ātrāk? Atbildi uz mūsu e-pastu un pasaki to.","live.h2":"Skaties, kā tas top, tiešraidē","live.caption":"Katra kartīte ir paslēpta: tu redzi darba formu, nevis vārdus.","live.watching.one":"tiešraidē: {n} skatās","live.watching.other":"tiešraidē: {n} skatās","live.last.now":"Pēdējā kartīte pārvietota tikko","live.last.min.one":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.min.other":"Pēdējā kartīte pārvietota pirms {n} min.","live.last.hour.one":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.hour.other":"Pēdējā kartīte pārvietota pirms {n} st.","live.last.day.one":"Pēdējā kartīte pārvietota pirms {n} d.","live.last.day.other":"Pēdējā kartīte pārvietota pirms {n} d.","live.offline":"Tiešraides tāfele mazliet atpūšas. Ieskaties drīz vēlreiz.","live.cols":"Backlogs|Darāmais|Procesā|Komanda pārbauda|Gaida tavu testu|Komandai|Izdarīts","pitch.words.zero":"{n} vārdu","pitch.letters.zero":"{n} burtu","pitch.chars.zero":"{n} rakstzīmju","count.line.html.zero":"Tāfelē šobrīd ir {n} kartīšu","tl.cards.zero":"{n} kartīšu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Deleģēts."]},{"n":2,"texts":["Robotu kanban.","Aģenti, sakārtoti.","Idejas, uzbūvētas."]},{"n":3,"texts":["Kanban robotiem.","Idejas kļūst funkcijās.","Bezmaksas aģentu kanban."]},{"n":5,"texts":["Kanban tāfele, ko vada aģenti.","Tu raksti kartītes. Aģenti būvē.","Bezmaksas, vietēja, pārbaudīta, mazliet jocīga."]},{"n":8,"texts":["Bezmaksas kanban tāfele, kur strādā MI aģenti.","Uzraksti ideju. Aģenti to uzbūvē. Tu to pieņem.","Agile vienam cilvēkam un daudziem pacietīgiem robotiem."]},{"n":13,"texts":["Kanban tāfele tavā datorā, kurā kartītes pa vienai paņem MI aģenti, kamēr tu atpūties.","Uzraksti ideju. To uzbūvē aģentu komanda. Pēc tam testētājs to rūpīgi pārbauda un parāda.","Bez kontiem, bez izsekotājiem: tāfele, daži roboti un tu, kas visu izlemj."]},{"n":21,"texts":["AI-gile ir kanban tāfele darbam ar MI programmēšanas aģentiem. Viņi paņem kartītes, bet tu tās pārbaudi un pieņem.","Katram projektam ir savs līderis un MI aģentu komanda. Komentē jebkuru kartīti, un komanda uzreiz ķeras pie darba.","Bezmaksas personīga darāmo lietu tāfele, kas darbojas tavā datorā. Darbinieki ir roboti. Tas, kurš saka jā, esi tu."]},{"n":34,"texts":["Tu liec idejas uz tāfeles. MI aģentu komanda pārvērš tās strādājošās funkcijās, pārbauda un atdod atpakaļ ar soļiem, kā izmēģināt. Nekas nav gatavs, kamēr tu to neesi pateicis.","AI-gile ir mājās darināta kanban tāfele, ko uzbūvēja Rich, lielā mērā ar to aģentu palīdzību, kurus tā tagad vada. Tā ir bezmaksas, darbojas tavā datorā un tiek dalīta ar draugiem, nevis pārdota.","Iedomājies parastu kanban tāfeli ar kolonnām no Backloga līdz Izdarītam, tikai kartītes paņem MI aģenti. Viņi ziņo par progresu, jautā, kad iestrēguši, un vienmēr gaida tavu īkšķi uz augšu."]},{"n":55,"texts":["AI-gile ir kanban tāfele, kurā komanda sastāv no MI aģentiem. Katram projektam ir līderis, kas plāno darbu, un palīgi, kas to būvē. Kad funkcija ir gatava, MI testētājs to izmēģina un uzņem ekrānuzņēmumu, tad tā nonāk tavā kaudzītē. Pieņem to vai komentē, un viņi darbu pārstrādā.","Tas sākās kā viena cilvēka veids, kā sekot daudzām MI programmēšanas sesijām vienlaikus, un izauga par īstu tāfeli. Tā darbojas tavā datorā, nevajag konta un nav izsekotāju. Tā ir bezmaksas draugiem un ikvienam ziņkārīgajam. Tā ir arī nepabeigta, tāpēc gaidi raupjas malas un reizēm kādu pārsteigumu.","Lūk, godīgā versija. Idejas tev joprojām jāizdomā, un rezultāti tev joprojām jāpārbauda. AI-gile dara visu pa vidu: tur kārtībā kartītes, pamodina īsto aģentu, kad tu komentē, parāda, kas tieši mainījies, un visu savāc vienā īsā kaudzītē, lai tev nav jāmeklē pa visiem projektiem un jāpārslēdzas starp lietotnēm."]},{"n":89,"texts":["AI-gile ir bezmaksas kanban tāfele, ko tu palaid savā datorā. Cilvēku vietā katram projektam ir sava MI aģentu komanda: līderis, kas tavas idejas pārvērš kartītēs un plānā, un palīgi, kas kartītes ķer pēc prioritātes. Kad kaut kas uzbūvēts, MI testētājs izpilda testa soļus un parāda, ko redzēja. Tad tas gaida vienā kaudzītē ar nosaukumu Tev. Tu to pieņem vai komentē, un komanda mēģina vēlreiz, ja vajag. Līdz Izdarīts nekas nenonāk bez tevis.","Dažas lietas, ko varbūt negaidi. Nakts sardze, kamēr tu guli, papildina kolonnu Darāmais ar kartītēm, kurām nevajag tavu atbildi. Tokenu skaitītājs rāda, cik aģenti šodien un šonedēļ iztērējuši, un režīms Bez tokeniem liek viņiem pārstāt tērēt. Tu vari rakstīt draugiem, un privātās ziņas ir šifrētas no gala līdz galam. Tāfele runā aptuveni 120 valodās, tostarp holandiešu, flāmu, pirātu un klingonu. Nekas no tā nemaksā ne santīma, un neviens arī necenšas tev to pārdot.","AI-gile ir neliels personīgs projekts, nevis uzņēmums. Rich gribēja pieskatīt vairākus MI programmēšanas projektus, neatverot katru lietotni, tāpēc viņš un aģenti uzbūvēja tāfeli, un tad ar to uzbūvēja pārējo pašu. Tā ir slēgtā pirmsalfā, kas nozīmē, ka lielākoties tā darbojas, bet to izmēģina tikai daži draugi. Neviens neko nepārdod, neviens nevāc tavus datus. Nav cenu lapas, nav jaunumu vēstuļu un nav izaugsmes plāna. Ja šķiet noderīgi, vari pieteikties izmēģināt, kad tā atvērsies nedaudz plašāk."]},{"n":144,"texts":["AI-gile ir kanban tāfele vienam cilvēkam un daudziem MI aģentiem. Tā darbojas tavā paša datorā un ir pilnīgi bezmaksas. Tu pievieno projektus, un katram projektam ir līderis un neliela komanda. Tu tērzē ar līderi, mazliet kā Discord, un apraksti ideju; līderis to pārvērš kartītēs un plānā, un tad gaida, kad nospiedīsi Aiziet. Komanda kartītes izstrādā pēc prioritātes, izmantojot vienkāršu komandrindu, kas radīta valodas modeļiem. Pirms kaut kas atgriežas pie tevis, MI testētājs izpilda soļus lietotnes kopijā un pievieno ekrānuzņēmumu. Pabeigtais darbs nonāk tavā kaudzītē kopā ar mainītajiem failiem un atšķirībām. Tu to pieņem vai atstāj komentāru, un komanda pamostas un mēģina vēlreiz. Tāfele sevi arī uzkopj: saistītās kartītes tiek apvienotas, un juceklīgi nosaukumi sakārtoti. Kartīti uz Izdarīts var pārvietot tikai tu. Neviens cits to nevar, pat visizcilākais aģents ne.","Aptuveni tāda ir diena ar AI-gile. Vakarā tu atstāj dažus komentārus: šī poga ir nepareizā vietā, šis saraksts jākārto, vai varētu būt tumšais režīms. Tu ej gulēt. Aģenti izlasa komentārus, veic izmaiņas, pārbauda tās un atdod tev atpakaļ. Ja Darāmais izsīkst, nakts sardze to papildina no backloga ar kartītēm, kurām nevajag tavu atbildi. Rītā ir viena īsa kaudzīte: pāris jautājumu un dažas lietas, ko izmēģināt, katrai ar soļiem, ko var izpildīt miegains cilvēks, un ekrānuzņēmumu, kā tas strādā. Tu pārklikšķini, pieņem labās un atsūti atpakaļ pārējās. Ja kaut kas nav skaidrs, tu vienkārši komentē, un tas atkal nonāk pie komandas. Tokenu skaitītājs rāda, cik tas viss patērēja, un režīms Bez tokeniem ir tievām nedēļām. Tad tu brokasto, kam aģenti vēl nevar palīdzēt.","Vispirms, kas AI-gile nav. Tas nav jaunuzņēmums, tas netiek pārdots, un neviens nevāc tavus datus. Tā ir bezmaksas tāfele, kas darbojas tavā datorā, bez kontiem, bez izsekotājiem un bez sīkdatnēm. Kas tā ir: viena kārtīga vieta, kur uzreiz redzēt visus MI programmēšanas projektus, kur kartītes dara aģentu komanda, bet lēmumus pieņem tu. Tajā ir arī nakts sardze, kas kartītes sagatavo, kamēr tu guli. Tā apvieno saistītās kartītes, sakārto juceklīgus nosaukumus un pieskata, cik kompakts paliek kods. Tā runā aptuveni 120 valodās, no holandiešu un flāmu līdz pirātu un klingonu. Draugi var sūtīt viens otram ziņas, privāti un šifrēti. To uzbūvēja Rich un liels pulks pacietīgu aģentu, galvenokārt izmantojot pašu tāfeli. Tā ir slēgtā pirmsalfā, tāpēc dažviet vēl ir raupja. Ja šķiet jautri, pieklājīgi pajautā, un varbūt tiksi iekšā agrāk."]}],"quips":{"1":"Viens vārds. Drosmīgi. Varbūt pat pārāk drosmīgi.","3":"Trīs vārdi. Jau godīgāk nekā vairums produktu lapu.","8":"Astoņi vārdi. Joprojām īsāk par stand-up.","21":"Garumi, starp citu, ir stāstu punkti. Protams, ka ir.","55":"Piecdesmit pieci vārdi. Kamēr tu to lasīji, divas kartītes tika pabeigtas.","144":"Tas ir garais. 233 nav. Aģenti ir aizgājuši gulēt."}},"timeline":{"first-idea.name":"Pirmā ideja","first-idea.line":"Pati pirmā saruna, pirms vēl bija kāds kods.","first-board.name":"Pirmā tāfele","first-board.line":"Tāfele, kas seko savai būvei: kartītes, kolonnas, vilkšana, projekti.","team-roles.name":"Komanda un lomas","team-roles.line":"Aģentu profili, komandu veidnes, telpas un kurš ko dara.","install.name":"Uzstādīšana un laidieni","install.line":"Zip, ko draugs var uzstādīt, pašatjaunināšanās, kanāli un atgriešanās.","usage-saver.name":"Patēriņa taupītājs","usage-saver.line":"Mēra, cik izmaksā darbs, uztur kodu kompaktu, taupa tavu limitu.","friends.name":"Draugi un kopīgošana","friends.line":"Privātas ziņas, sajaukts releja kanāls, ielūgumi, lomas un kopīgi projekti.","languages.name":"Valodas","languages.line":"Katrs ekrāna teksts valodas failā, vispirms holandiešu un flāmu valoda.","ai-tester.name":"MI testētājs","ai-tester.line":"Testētājs vispirms pārbauda katru nodošanu un parāda redzēto.","website.name":"Mājaslapa","website.line":"aigile.lol, ievada lapa un šī laika līnija.","streaming.name":"Tērzēšana un straumēšana","streaming.line":"Discord, Twitch, OBS, straumētāja režīms, GIF un emocijzīmes.","no-ai.name":"Izdevums bez MI","no-ai.line":"Tāfele cilvēkiem, kas programmē bez MI, un publiskas tāfeles.","night-watch.name":"Nakts sardze","night-watch.line":"Sargs un Scrum Master notur komandas pie darba, kamēr tu guli.","p-more.name":"Viss pārējais","p-more.line":"Mazākas idejas, kas vēl gaida savu kārtu.","p-android.name":"Telefons un Android","p-android.line":"Piekļuve tāfelei no telefona, pēc tam dabiska Android lietotne.","p-release.name":"Alfa un tālāk","p-release.line":"Slēgtā alfa, dzīvā vietne, tad beta.","p-languages.name":"Vairāk valodu","p-languages.line":"130 valodas un iegremdēšanās režīms tiem, kas mācās.","p-engines.name":"Vairāk MI dzinēju","p-engines.line":"Katram aģentam izvēlies Claude, Codex, Gemini, Copilot vai Cursor.","p-pro.name":"Profesionāla prakse","p-pro.line":"Riska atzīmes, sapludināšanas vārti, incidentu kartītes un aizsargbarjeras.","p-self.name":"Rūpes par tevi","p-self.line":"Noguruma režīms, atgādinājumi par sevis kopšanu un 4:20.","p-servers.name":"Serveri un mērogs","p-servers.line":"Globāli servera iestatījumi, lomas un plānošana izaugsmei.","p-livestream.name":"Straumēšanas papildinājumi","p-livestream.line":"Twitch tērzētava, pašu emocijzīmes un publisks tiešraides skats."},"words":{"button":"📖 Nozares žargons","h":"📖 Vārdi paskaidroti","intro":"Bezmaksas mācības vienkāršā valodā: visi jēdzieni no pirmās idejas līdz uzticamam pakalpojumam, pa ceļam iepazīstot Agile, izstrādi, drošību un darbu ar AI.","search":"Meklēt vārdu…","none":"Neviens vārds neatbilst.","close":"Aizvērt","count":{"one":"{count} vārds","other":"{count} vārdi"},"groups":[{"id":"idea","name":"💡 Ideja un izpēte"},{"id":"plan","name":"🗺️ Darba plānošana"},{"id":"agile","name":"🔁 Agile darba veidi"},{"id":"build","name":"🛠️ Būvēšana"},{"id":"test","name":"🧪 Testēšana un kvalitāte"},{"id":"change","name":"🔀 Droša mainīšana"},{"id":"run","name":"🛎️ Pakalpojuma uzturēšana"},{"id":"sec","name":"🔒 Drošība un privātums"},{"id":"ai","name":"🤖 Darbs ar AI"},{"id":"money","name":"💰 Nauda un licences"}],"list":[{"id":"discovery","g":"idea","word":"Izpēte","text":"Sākotnējais posms, kad pirms veidošanas noskaidro, kuru problēmu un kam ir vērts risināt.","also":["izpētes posms","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problēmas formulējums","text":"Viens vai divi teikumi par to, kam ir problēma, kāda tā ir un kāpēc svarīga, lai visi tiektos uz vienu mērķi.","also":["problēmas formulējumi","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Lietotājs","text":"Cilvēks, kas izmanto tavu izveidoto risinājumu. Darba mērķis ir apmierināt viņa vajadzības.","also":["lietotāji","lietotāja","lietotāju","lietotājam","lietotājiem","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Ieinteresētā puse","text":"Ikviens, kuru interesē vai ietekmē darba iznākums, piemēram, maksātāji, lietotāji vai atbalsta sniedzēji.","also":["ieinteresētās puses","ieinteresēto pušu","ieinteresētajām pusēm","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Izdomāts, bet ticams cilvēks, kas pārstāv vienu lietotāju veidu, lai komanda varētu jautāt: „Vai Samam tas būtu viegli?”","also":["persona"]},{"id":"userresearch","g":"idea","word":"Lietotāju izpēte","text":"Sarunas ar īstiem cilvēkiem un viņu novērošana, lai uzzinātu viņu vajadzības, nevis minētu.","also":["lietotāju intervijas","user research","user interviews"]},{"id":"journey","g":"idea","word":"Lietotāja ceļš","text":"Soļi, ko cilvēks veic līdz mērķim, no pirmās uzzināšanas līdz pabeigšanai, arī ārpus tava produkta. To attēlošana parāda, kur rodas grūtības.","also":["lietotāju ceļi","klienta ceļš","user journey","customer journey","user journeys"]},{"id":"painpoint","g":"idea","word":"Sāpju punkts","text":"Tas, kas cilvēkus pašlaik kaitina vai kavē. Labi produkti šīs grūtības novērš.","also":["sāpju punkti","sāpju punkta","sāpju punktu","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Pieņēmums","text":"Tas, kam tici, bet kas vēl nav pārbaudīts. Pierakstīti pieņēmumi palīdz izvēlēties, ko pārbaudīt vispirms.","also":["pieņēmumi","pieņēmuma","pieņēmumu","pieņēmumiem","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotēze","text":"Pamatots minējums, ko plāno pārbaudīt, ar paredzamo iznākumu, piemēram, „cilvēki reģistrēsies, ja pirmais mēnesis būs bez maksas”.","also":["hipotēzes","hipotēzi","hipotēžu","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperiments","text":"Neliels plānots izmēģinājums, lai pirms lielāka ieguldījuma noskaidrotu, vai ideja darbojas.","also":["eksperimenti","eksperimenta","eksperimentu","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Koncepcijas pārbaude (PoC)","text":"Ātrs, aptuvens izmēģinājums, vai ideja vispār var darboties. Kad atbilde iegūta, to parasti atmet.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototips","text":"Agrīns produkta modelis, bieži klikšķināmi attēli, lai izmēģinātu ideju ar cilvēkiem pirms īstas izstrādes.","also":["prototipi","prototipa","prototipu","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Ekrāna shēma","text":"Vienkārša ekrāna skice, kas parāda elementu izvietojumu bez krāsām un īsta satura.","also":["ekrānu shēmas","wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Makets","text":"Detalizēts topošā ekrāna attēls ar īstām krāsām un tekstu, bet vēl nekas nedarbojas.","also":["maketi","maketa","maketu","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Biznesa pamatojums","text":"Iemesli projekta īstenošanai: izmaksas, ieguvumi vai ietaupījumi un riski.","also":["biznesa pamatojumi","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Īstenojamība","text":"Vai kaut ko tiešām var izveidot un uzturēt ar pieejamo laiku, naudu un prasmēm.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"Ieguvums","text":"Pārmaiņa, ko vēlies cilvēkiem, piemēram, mazāk nokavētu vizīšu. Tā ir svarīgāka par paveiktā apjomu.","also":["ieguvumi","ieguvuma","ieguvumu","iznākums","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Izveidotais rezultāts","text":"Tas, ko komanda izveido, piemēram, jauns ekrāns vai pārskats. Izveidošana pati par sevi vēl nenozīmē, ka tas kādam palīdz.","also":["rezultāti","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Panākumu rādītājs","text":"Skaitlis, kas parāda, vai darbs sasniedzis mērķi, piemēram, vairāk cilvēku pabeidz pasūtījumu.","also":["panākumu rādītāji","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Galvenais darbības rādītājs (KPI)","text":"Svarīgs skaitlis, ko vēro, lai saprastu, vai viss rit labi, piemēram, reģistrāciju skaits nedēļā.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Mērķi un galvenie rezultāti (OKR)","text":"Mērķu noteikšanas veids: mērķis pasaka, ko vēlies, bet daži izmērāmi galvenie rezultāti parāda, ka tas sasniegts.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produkts","text":"Tas, ko veido un uztur lietotājiem, piemēram, lietotne, vietne vai rīks.","also":["produkti","produkta","produktu","produktā","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Produkta vīzija","text":"Īss apraksts par to, kam produkts palīdz un kādā virzienā ilgtermiņā attīstās.","also":["vīzijas formulējums","vision statement"]},{"id":"po","g":"plan","word":"Produkta īpašnieks (PO)","text":"Cilvēks, kurš izlemj, ko veidot un kādā secībā, lai komanda vienmēr strādātu pie svarīgākā. AI-gile tas esi tu.","also":["PO","produkta īpašnieki","product owners"]},{"id":"pm","g":"plan","word":"Produkta vadītājs (PM)","text":"Cilvēks, kurš rūpējas par produkta virzību: kādas problēmas tas risina, kam un kāpēc. PM var nozīmēt arī projekta vadītāju, tāpēc precizē nozīmi.","also":["produkta vadītāji","product managers"]},{"id":"projmgr","g":"plan","word":"Projekta vadītājs","text":"Cilvēks, kurš seko projekta termiņiem un budžetam, uzraugot, kurš ko dara un līdz kuram laikam.","also":["projektu vadītāji","project managers"]},{"id":"roadmap","g":"plan","word":"Ceļa karte","text":"Aptuvens plāns par nākamajos mēnešos gaidāmo secīgā kārtībā. Tas rāda virzienu, nevis precīzus datumus, un mainās līdz ar jaunām zināšanām.","also":["ceļa kartes","ceļa karti","attīstības plāns","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Atskaites punkts","text":"Svarīgs brīdis projektā, piemēram, „pirmā versija pieejama” vai „100 lietotāju”.","also":["atskaites punkti","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Minimālais dzīvotspējīgais produkts (MVP)","text":"Mazākā produkta versija, kas jau noder īstiem cilvēkiem, lai varētu agri mācīties no viņu pieredzes.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Prasība","text":"Tas, kas gatavajam produktam ir jāspēj vai kādam tam jābūt.","also":["prasības","prasību","prasībām","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Darba tvērums","text":"Kas darbā ietilpst un, tikpat svarīgi, kas neietilpst.","also":["tvērumā","ārpus tvēruma","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Tvēruma nemanāma paplašināšanās","text":"Darbam pamazām pievieno arvien vairāk, nevienojoties par papildu laiku vai izmaksām, tāpēc tas nekādi nebeidzas.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Funkcija","text":"Viena lieta, ko produkts spēj paveikt cilvēka labā, piemēram, atiestatīt paroli.","also":["funkcijas","funkciju","funkcijai","funkcijām","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epiks","text":"Liels darbs, ko nevar paveikt vienā reizē, tāpēc to sadala mazākās kartītēs.","also":["epiki","epika","epiku","epic","epics"]},{"id":"story","g":"plan","word":"Lietotājstāsts","text":"Neliels darbs no lietotāja skatpunkta: „Kā pircējs vēlos saglabāt grozu, lai varētu turpināt vēlāk.” Tas sāk sarunu par to, ko veidot.","also":["lietotājstāsti","lietotājstāsta","lietotājstāstu","user story","user stories"]},{"id":"ac","g":"plan","word":"Pieņemšanas kritēriji (AC)","text":"Pirms darba sākuma saskaņotas pārbaudes, kurām kartītei jāatbilst, lai to uzskatītu par pabeigtu, piemēram, „grozs saglabājas pēc izrakstīšanās un atkārtotas pierakstīšanās”.","also":["pieņemšanas kritēriji","acceptance criteria"]},{"id":"task","g":"plan","word":"Uzdevums","text":"Viens paveicams darbs, bieži neliels solis lielākā lietotājstāstā.","also":["uzdevumi","uzdevuma","uzdevumu","uzdevumiem","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Darba pieteikums","text":"Cits kartītes nosaukums: viens darbs vai pieprasījums, kam seko no sākuma līdz beigām.","also":["darba pieteikumi","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritāte","text":"Cik svarīgs vai steidzams kaut kas ir salīdzinājumā ar pārējo, lai svarīgākais tiktu paveikts vispirms.","also":["prioritātes","prioritāti","prioritāšu","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritāšu noteikšana","text":"Darbu sakārtošana pēc svarīguma. Izplatīta metode ir MoSCoW: obligāti vajag, vajadzētu, varētu un šoreiz nebūs.","also":["prioritizēšana","MoSCoW"]},{"id":"estimate","g":"plan","word":"Novērtējums","text":"Pamatots minējums par darba apjomu vai ilgumu. Tas ir minējums, nevis solījums.","also":["novērtējumi","novērtējuma","novērtējumu","novērtēšana","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Stāsta punkti","text":"Darba apjoma vērtēšana, salīdzinot kartītes, piemēram, „apmēram divreiz lielāka par to”, nevis skaitot stundas. Tos neizmanto komandu salīdzināšanai.","also":["stāsta punkts","story points","story point"]},{"id":"tshirt","g":"plan","word":"Vērtēšana pēc T kreklu izmēriem","text":"Darba apjoma vērtēšana ar S, M, L vai XL. Ātri un pietiekami labi sākotnējai plānošanai.","also":["T kreklu izmēri","T-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Plānošanas pokers","text":"Vērtēšanas spēle: visi reizē parāda apjoma kartīti, tad lielākā un mazākā vērtējuma devēji paskaidro savu izvēli.","also":["planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"Atkarība","text":"Kad viens darbs nevar sākties vai beigties, pirms pabeigts cits.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Šķērslis","text":"Viss, kas pašlaik aptur darba virzību, piemēram, trūkstoša atbilde vai bojāts rīks.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"Termiņš","text":"Datums, līdz kuram kaut kam jābūt pabeigtam.","also":["termiņi","termiņa","termiņu","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Nododamais rezultāts","text":"Konkrēta lieta, ko darba gaitā izveido un nodod, piemēram, strādājoša lapa vai pārskats.","also":["nododamie rezultāti","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prognoze","text":"Paredzējums par iespējamo notikumu, piemēram, darba pabeigšanas laiku, balstoties uz pašreiz zināmo.","also":["prognozes","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Rādītājs","text":"Jebkas, ko mēri un vēro laika gaitā, piemēram, lapas apmeklējumi vai labošanai vajadzīgais laiks.","also":["metric","metrics"]},{"id":"feedback","g":"plan","word":"Atgriezeniskā saite","text":"Tas, ko cilvēki saka par tavu darbu — gan labais, gan sliktais. Agra un bieža atgriezeniskā saite ir Agile pamatā.","noTip":1},{"id":"backlog","g":"agile","word":"Backlogs","text":"Gaidošo ideju un vēl neieplānoto darbu saraksts ar svarīgāko augšā. Pie tiem nestrādā, kamēr tie nav pārvietoti uz „Darāmais”."},{"id":"sprint","g":"agile","word":"Sprints","text":"Īss, noteikta ilguma darba posms (bieži viena vai divas nedēļas, nekad ilgāks par mēnesi) ar mērķi un saskaņotām pabeidzamām kartītēm.","also":["sprinti","sprinta","sprintu","sprintam","sprintiem","sprintā","sprintos"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Īsa ikdienas apspriede: ko katrs komandas dalībnieks paveicis, ko darīs tālāk un kas traucē. Scrum pieejā to sauc par ikdienas Scrum.","also":["stand-upi","stand-upa","stand-upu","ikdienas sapulce","ikdienas Scrum","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Darba pieeja, kur kartītes pārvietojas starp dēļa kolonnām, piemēram, „Darāmais”, „Procesā” un „Izdarīts”, un komanda ierobežo vienlaikus iesāktā apjomu, lai darbs plūstu raiti."},{"id":"wip","g":"agile","word":"WIP limits","text":"WIP nozīmē iesākto darbu. WIP ierobežojums nosaka lielāko kartīšu skaitu vienā kolonnā, lai komanda pabeigtu darbus, pirms sāk jaunus.","also":["WIP"]},{"id":"dod","g":"agile","word":"Pabeigts definīcija","text":"Komandas īss kontrolsaraksts, ko nozīmē „pabeigts”, piemēram, notestēts un paskaidrots, pirms kartīte tiek nodota tev. Tās dvīne, Gatavs sākšanai definīcija, nosaka, kad kartīte ir pietiekami skaidra, lai sāktu.","also":["Gatavs sākšanai definīcija","Pabeigts definīcija","Definition of Done","Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Regulāra atskatīšanās uz komandas darbu, lai vienotos par vienu vai diviem uzlabojumiem nākamajai reizei. Retro ir saīsinājums no vārda „retrospektīva”. AI-gile retro ierosina izmaiņu komandas darba kārtībā, un tu saki Go vai Vēl ne.","also":["retrospektīva","retrospektīvas","retrospektīvu"]},{"id":"swarm","g":"agile","word":"Spiets","text":"Visi palīgā: daudzi atliek citus darbus, lai kopā atrisinātu vienu steidzamu lietu. AI-gile visas komandas palīdz vienam projektam, kamēr pārējie projekti gaida.","also":["spietā","spietu","spieta"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrum pieejā šis cilvēks palīdz komandai labi strādāt: novērš šķēršļus, uztur sapulču virzību un māca labus ieradumus, nevienu nekomandējot. AI-gile Lead Scrum Master pamana iestrēgušas kartītes, mudina komandas un visos projektos atgādina tev par gaidošo.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (spējā pieeja)","text":"Darbs mazos soļos: izveido nedaudz, bieži rādi īstus rezultātus, mācies no atsauksmēm un pielāgo plānu, nevis izplāno visu iepriekš.","also":["spējā izstrāde","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile manifests","text":"Īss paziņojums, ko programmatūras veidotāji uzrakstīja 2001. gadā. Tas dod priekšroku cilvēkiem, strādājošiem rezultātiem, sadarbībai ar klientiem un atsaucībai uz pārmaiņām, nevis smagiem plāniem un dokumentiem.","also":["Spējās programmatūras izstrādes manifests","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Ūdenskrituma modelis","text":"Senāks darba veids: visu izplāno, tad visu izveido un pēc tam visu testē, vienu posmu pēc otra. Vēlas izmaiņas ir grūtas un dārgas.","also":["waterfall","waterfall model"]},{"id":"iteration","g":"agile","word":"Iterācija","text":"Viens veidošanas, pārbaudes un uzlabošanas cikls. Agile darbs sastāv no šādiem cikliem, un sprints ir viens to veids.","also":["iterācijas","iterāciju","iterācijā","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrements","text":"Jauna, strādājoša produkta daļa, kas pievienota sprintā vai darba ciklā un sader ar jau esošo.","also":["inkrementi","inkrementa","inkrementu","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Populārs Agile darba veids: neliela komanda īsos sprintos virzās uz mērķi, ar noteiktām lomām un regulārām plānošanas, pārbaudes un uzlabošanas sanāksmēm."},{"id":"scrumteam","g":"agile","word":"Scrum komanda","text":"Neliela grupa, kas veic darbu Scrum pieejā: produkta īpašnieks, Scrum Master un izstrādātāji.","also":["Scrum komandas","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum pasākumi","text":"Regulārās Scrum sanāksmes: sprinta plānošana, ikdienas Scrum, sprinta pārskats un retrospektīva. Daudzi tās sauc par ceremonijām.","also":["ceremonijas","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprinta plānošana","text":"Sanāksme sprinta sākumā, kur komanda vienojas, kāpēc sprints ir svarīgs, kuras kartītes uzņemties un kā sākt.","also":["plānošanas sanāksme","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprinta mērķis","text":"Viens teikums, kas pasaka, kam sprints paredzēts. Sīkie uzdevumi var mainīties, ja vien mērķis tiek sasniegts.","also":["sprinta mērķi","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprinta backlogs","text":"Pašreizējam sprintam izvēlētās kartītes un komandas plāns to paveikšanai.","also":["sprinta backlogi","sprinta backloga","sprinta backlogu","sprinta darbu saraksts","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Produkta backlogs","text":"Pilns sakārtots saraksts ar visu, ko produktā varētu izveidot, svarīgākais augšā. Tas mainās līdz ar jaunām zināšanām.","also":["produkta backlogi","produkta backloga","produkta backlogu","produkta darbu saraksts","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Produkta mērķis","text":"Lielākais rezultāts, uz ko produkts tiecas un kas palīdz komandai izvēlēties nākamo darbu.","also":["produkta mērķi","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Backloga precizēšana","text":"Regulāra backloga pārskatīšana: kartītes sakārto, sadala, nosaka to secību un papildina ar detaļām, lai tās būtu gatavas darbam. To sauc arī par backlog grooming.","also":["backloga precizēšanu","darbu saraksta precizēšana","backloga sakārtošana","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprinta pārskats","text":"Sanāksme sprinta beigās, kur komanda rāda paveikto un uzklausa atsauksmes, lai lemtu, kas sekos.","also":["sprinta pārskati","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demonstrācija","text":"Gatavā darba parādīšana darbībā cilvēkiem, kas to pieprasīja.","also":["demonstrācijas","demonstrāciju","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Laika ietvars","text":"Noteikts laiks kādai darbībai. Kad tas beidzas, apstājas, pat ja viss vēl nav paveikts.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Komandas ātrums","text":"Darba apjoms, ko komanda parasti pabeidz sprintā un ko izmanto nākamā sprinta plānošanai. Tas nav cilvēku centības vērtējums.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Darba jauda","text":"Cik daudz darba komanda var uzņemties noteiktā laikā, ņemot vērā atvaļinājumus un citus pienākumus.","noTip":1},{"id":"burndown","g":"agile","word":"Atlikušā darba diagramma","text":"Diagramma, kur sprinta atlikušā darba apjoms samazinās dienu no dienas. Ja līnija paliek līdzena, kaut kas iestrēdzis.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Pabeigtā darba diagramma","text":"Diagramma, kur paveiktā apjoms laika gaitā aug līdzās kopējam plānam, ļaujot redzēt, kad sasniegsi mērķi.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban dēlis","text":"Pats dēlis: katram darba posmam sava kolonna, pa kurām pārvietojas kartītes.","also":["Kanban dēļi","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Vilkšanas sistēma","text":"Darba veids, kur jaunu darbu sāk tikai tad, kad kādam ir vieta to uzņemties, nevis to uzkrauj tam, kam jau tā darba ir par daudz.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Darba plūsma","text":"Cik raiti darbs virzās pa dēli. Labā plūsmā kartītes kustas uz priekšu, nevis krājas.","also":["plūsma","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Izpildes laiks","text":"Laiks no pieprasījuma saņemšanas līdz tā izpildei.","also":["izpildes laiki","lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Cikla laiks","text":"Laiks no brīža, kad kartītes darbu tiešām sāk, līdz tā pabeigšanai.","also":["cikla laiki","cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Caurlaidspēja","text":"Cik kartīšu pabeidz nedēļā vai citā noteiktā laika posmā.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Šaurā vieta","text":"Posms, kur darbs sakrājas un palēnina visu turpmāko, gluži kā pudeles šaurais kakliņš.","also":["šaurās vietas","šauro vietu","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Peldjosla","text":"Horizontāla josla uz dēļa, kas grupē viena veida kartītes, piemēram, steidzamus darbus vai vienas komandas kartītes.","also":["peldjoslas","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Darba pieeja, kas novērš izšķērdēšanu jeb visu, kas nepalīdz klientam, un uztur raitu darba plūsmu."},{"id":"waste","g":"agile","word":"Izšķērdēšana","text":"Lean pieejā — viss, kas prasa piepūli, bet nepalīdz klientam, piemēram, gaidīšana, pārtaisīšana vai nevienam nevajadzīgu lietu veidošana.","noTip":1},{"id":"kaizen","g":"agile","word":"Nepārtraukta uzlabošana","text":"Pastāvīga uzlabošanās ar nelielām regulārām izmaiņām un pārbaudi, vai tās palīdzējušas. Retrospektīvas ir viens veids, kā to darīt. To sauc arī par kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Pašorganizējoša komanda","text":"Komanda, kas pati izlemj, kā paveikt darbu, nevis gaida norādījumus katram solim.","also":["pašvadīta komanda","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Daudzfunkcionāla komanda","text":"Komanda ar visām prasmēm, lai pati pabeigtu darbu, piemēram, projektēšanu, izstrādi un testēšanu.","also":["starpfunkcionāla komanda","cross-functional"]},{"id":"spike","g":"agile","word":"Izpētes uzdevums","text":"Īsa izpēte ar laika ierobežojumu, lai atbildētu uz jautājumu pirms pamatdarba uzņemšanās.","also":["izpētes uzdevumi","spike","spikes"]},{"id":"rework","g":"agile","word":"Pārtaisīšana","text":"Darba veikšana vēlreiz, jo pirmajā reizē tas nebija pareizs.","also":["reworked"]},{"id":"safe","g":"agile","word":"Agile mērogošana (SAFe)","text":"Agile izmantošana daudzās komandās lielā organizācijā. SAFe jeb Scaled Agile Framework ir viens pazīstams piemērs.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Projekta koda mape ar pilnu commitu vēsturi. Tā var atrasties tavā datorā, GitHub vai abās vietās.","also":["repozitorijs","repozitorija"]},{"id":"branch","g":"build","word":"Branch","text":"Atsevišķa darba līnija kodā, lai izmaiņas varētu veikt, neskarot galveno versiju.","also":["branches","zars","zara","zari"]},{"id":"commit","g":"build","word":"Commit","text":"Saglabāts koda momentuzņēmums ar īsu piezīmi par to, kas mainījās. Vienmēr var atgriezties pie kāda no tiem.","also":["commits","commiti","commita","commitu"]},{"id":"push","g":"build","word":"Push","text":"Saglabāto momentuzņēmumu (commitu) nosūtīšana no šī datora uz koplietotu tiešsaistes kopiju, piemēram, GitHub, lai tie būtu dublēti un citi varētu tos saņemt."},{"id":"merge","g":"build","word":"Merge","text":"Viena zara izmaiņu apvienošana ar citu, parasti atpakaļ galvenajā versijā."},{"id":"pr","g":"build","word":"Pull request","text":"Lūgums pārbaudīt zara izmaiņas un apvienot tās ar galveno versiju. Dažās vietnēs to sauc par merge request.","also":["PR","PRs","apvienošanas pieprasījums","merge request"]},{"id":"refactor","g":"build","word":"Refaktorēšana","text":"Koda sakārtošana, nemainot to, ko tas dara: mazāki faili, skaidrāki nosaukumi, mazāk atkārtojumu."},{"id":"bug","g":"build","word":"Kļūda","text":"Kaut kas, kas nedarbojas tā, kā vajadzētu.","also":["kļūdas","kļūdu","kļūdai","kļūdām","bugs","bugi","buga"]},{"id":"peerreview","g":"build","word":"Kolēģu pārskats","text":"Otrs acu pāris: darbu pirms tevis pārbauda kāds cits, nevis autors, lai mazāk kļūdu paliktu nepamanītas. AI-gile katru kartīti pārbauda cits AI.","also":["kolēģu pārskata","kolēģu pārskatu","koda pārskats"]},{"id":"code","g":"build","word":"Kods","text":"Rakstītas instrukcijas, kas datoram pasaka, ko darīt. To sauc arī par pirmkodu.","also":["pirmkods","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programmēšanas valoda","text":"Valoda koda rakstīšanai, piemēram, JavaScript, Python vai Java. Dažādas valodas der dažādiem darbiem.","also":["programmēšanas valodas","programming languages"]},{"id":"developer","g":"build","word":"Izstrādātājs (dev)","text":"Cilvēks, kas raksta un maina kodu. Viņu sauc arī par programmētāju vai programmatūras inženieri.","also":["izstrādātājs","izstrādātāji","programmētājs","programmatūras inženieris","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Programmatūra","text":"Programmas datoros un tālruņos pretstatā pašām ierīcēm jeb aparatūrai.","noTip":1},{"id":"app","g":"build","word":"Lietotne","text":"Programma, ko cilvēki izmanto kāda darba paveikšanai tālrunī, datorā vai tīmekļa pārlūkā.","also":["lietotnes","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Tīmekļa lietotne","text":"Lietotne, kas darbojas tīmekļa pārlūkā, tāpēc nekas nav jāinstalē.","also":["tīmekļa lietotnes","web apps","web application"]},{"id":"frontend","g":"build","word":"Priekšgals","text":"Lietotnes daļa, ko redzi un uz kuras klikšķini: ekrāni, pogas un teksts, bieži tavā pārlūkā.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Aizmugursistēma","text":"Lietotnes aizkulišu daļa, kas glabā datus un veic darbu, kad kaut ko nospied, piemēram, pārbauda paroli.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Pilna cikla izstrāde","text":"Darbs gan ar lietotnes priekšgalu, gan aizmugursistēmu.","also":["full stack","full-stack"]},{"id":"ui","g":"build","word":"Lietotāja saskarne (UI)","text":"Tas, ko cilvēks redz un izmanto ekrānā: izkārtojums, pogas, izvēlnes un teksts.","also":["UI","lietotāja saskarne","user interface"]},{"id":"ux","g":"build","word":"Lietotāja pieredze (UX)","text":"Kā ir kaut ko lietot: viegli, saprotami un patīkami vai mulsinoši un lēni.","also":["UX","lietotāja pieredze","user experience"]},{"id":"accessibility","g":"build","word":"Piekļūstamība (a11y)","text":"Risinājumu veidošana tā, lai tos var lietot ikviens, arī cilvēki ar vāju redzi, bez iespējas lietot peli vai ar ekrāna lasītāju.","also":["a11y"]},{"id":"responsive","g":"build","word":"Pielāgojams dizains","text":"Lapu pielāgošana jebkura izmēra ekrānam no tālruņa līdz lielam monitoram, lai tās labi darbotos."},{"id":"designsys","g":"build","word":"Dizaina sistēma","text":"Kopīgs krāsu, fontu, pogu un noteikumu komplekts, lai visi ekrāni izskatītos un darbotos vienādi.","also":["dizaina sistēmas","design systems"]},{"id":"architecture","g":"build","word":"Arhitektūra","text":"Sistēmas kopējā uzbūve: galvenās daļas un tas, kā tās sazinās."},{"id":"database","g":"build","word":"Datubāze (DB)","text":"Sakārtota informācijas krātuve, līdzīga ļoti jaudīgai izklājlapai, ko lietotne var lasīt un mainīt.","also":["datubāze","datubāzes","datubāzi","datubāzē","database","databases","DB"]},{"id":"schema","g":"build","word":"Datubāzes shēma","text":"Datubāzes uzbūve: kādas informācijas tabulas tajā ir un ko glabā katrā.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Strukturētā vaicājumu valoda: valoda, ar kuru daudzām datubāzēm pieprasa informāciju vai to maina.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dati","text":"Datorā glabāta informācija, piemēram, vārdi, pasūtījumi vai iestatījumi.","also":["datu kopa","datu kopas","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Serveris","text":"Dators, kas ir pastāvīgi ieslēgts un atbild uz citu datoru pieprasījumiem, piemēram, nosūta tīmekļa lapu, kad to apmeklē.","also":["serveri","servera","serverī","serveru","servers"]},{"id":"client","g":"build","word":"Klients","text":"Puse, kas kaut ko pieprasa, parasti tavs pārlūks vai lietotne, kas sazinās ar serveri. Uzņēmējdarbībā tas nozīmē arī pircēju.","also":["klienti","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Lietojumprogrammu saskarne: noteikts pieprasījumu klāsts, ko viena programma var nosūtīt otrai, piemēram, pajautāt laikapstākļu dienestam šodienas prognozi.","also":["APIs","lietojumprogrammu saskarne","application programming interface"]},{"id":"endpoint","g":"build","word":"Galapunkts","text":"Viena API piedāvāta iespēja: tīmekļa adrese, kuru programma var izsaukt, lai kaut ko saņemtu vai nosūtītu.","also":["galapunkti","endpoint","endpoints"]},{"id":"integration","g":"build","word":"Integrācija","text":"Divu sistēmu savienošana kopīgam darbam, piemēram, veikals nosūta pasūtījumus grāmatvedības programmai.","also":["integrācijas","integrations"]},{"id":"webhook","g":"build","word":"Tīmekļa aizķere","text":"Ziņojums, ko viena sistēma automātiski nosūta otrai, tiklīdz kaut kas notiek, piemēram, „maksājums saņemts”.","also":["tīmekļa aizķeres","webhook","webhooks"]},{"id":"library","g":"build","word":"Bibliotēka","text":"Cita cilvēka uzrakstīts gatavs kods, ko vari izmantot atkārtoti, nevis rakstīt visu no jauna.","also":["bibliotēkas","bibliotēku","bibliotēkā","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Ietvars","text":"Gatava struktūra lietotnes veidošanai, kas lielā mērā nosaka koda izkārtojumu, līdzīgi mājas karkasam, ko aizpildi.","also":["framework","frameworks"]},{"id":"sdk","g":"build","word":"Programmatūras izstrādes komplekts (SDK)","text":"Rīku, koda un piemēru komplekts programmatūras veidošanai noteiktai platformai vai pakalpojumam.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Programmatūras atkarība","text":"Bibliotēka vai rīks, kas vajadzīgs tava koda darbībai. Drošības dēļ tie jāatjaunina.","also":["programmatūras atkarības","software dependencies"]},{"id":"package","g":"build","word":"Pakotne","text":"Gatava koda kopums, ko vari instalēt un izmantot projektā.","also":["pakotnes","pakotni","pakotņu","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakotņu pārvaldnieks","text":"Rīks, kas iegūst un atjaunina kodam vajadzīgās pakotnes. Bieži izmanto npm.","also":["pakotņu pārvaldnieki","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Visplašāk lietotais rīks koda izmaiņu vēstures glabāšanai, commitu un zaru veidā."},{"id":"github","g":"build","word":"GitHub","text":"Vietne Git repozitoriju glabāšanai tiešsaistē, lai komandas var dalīties ar kodu, pārskatīt izmaiņas un sekot darbiem."},{"id":"vcs","g":"build","word":"Versiju kontrole","text":"Visu failu izmaiņu vēstures glabāšana, lai redzētu, kurš ko mainījis, un vajadzības gadījumā atgrieztos iepriekšējā stāvoklī. To dara Git.","also":["pirmkoda kontrole","source control","version control system"]},{"id":"clone","g":"build","word":"Klonēšana","text":"Pilnas repozitorija kopijas izveide savā datorā kopā ar tā vēsturi.","also":["klonēts","cloned","cloning"]},{"id":"pull","g":"build","word":"Izmaiņu saņemšana","text":"Jaunāko commitu iegūšana savā datorā no koplietotās kopijas, piemēram, GitHub. Pretējs darbībai push.","also":["pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Galvenais zars","text":"Oficiālā koda versija, no kuras visi sāk darbu, bieži saukta par main vai master.","also":["main","master branch"]},{"id":"conflict","g":"build","word":"Apvienošanas konflikts","text":"Divas izmaiņas atšķirīgi skar tās pašas rindas, tāpēc dators tās nevar apvienot un cilvēkam jāizvēlas risinājums.","also":["apvienošanas konflikti","merge conflicts"]},{"id":"diff","g":"build","word":"Atšķirību skats","text":"Skats, kas precīzi parāda atšķirības starp divām versijām: pievienotās un dzēstās rindas.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Atzarojums","text":"Tava kopija no cita cilvēka repozitorija, ko vari mainīt, neietekmējot oriģinālu.","also":["atzarojumi","forks","forked"]},{"id":"script","g":"build","word":"Skripts","text":"Īsa programma, kas pati veic vienu darbu, piemēram, sakārto failus vai palaiž lietotni.","also":["skripti","skripta","skriptu","scripts"],"noTip":1},{"id":"build","g":"build","word":"Būvējums","text":"Koda pārvēršana palaišanai gatavā formā vai pats gatavais rezultāts.","also":["būvējumi","būvējuma","būvējumu","build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilēšana","text":"Cilvēka rakstīta koda pārvēršana formā, ko dators var tieši izpildīt.","also":["kompilēts","kompilators","compiler"]},{"id":"cli","g":"build","word":"Komandrinda (CLI)","text":"Teksta logs, kur datoram ieraksti norādījumus klikšķināšanas vietā. To sauc arī par termināli.","also":["komandrinda","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Konfigurācija","text":"Iestatījumi, kas nosaka programmatūras darbību un ir atdalīti no koda, lai tos viegli mainītu.","also":["iestatījumi","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Vides mainīgais","text":"Iestatījums, ko programma saņem palaišanas brīdī, bieži adresēm vai parolēm, lai tās nebūtu jāraksta kodā.","also":["vides mainīgie","environment variables","env var"]},{"id":"debugging","g":"build","word":"Atkļūdošana","text":"Nedarbošanās cēloņa meklēšana un novēršana.","also":["atkļūdot","atkļūdošanu","debug","debugged"]},{"id":"pairing","g":"build","word":"Pāru programmēšana","text":"Divi cilvēki vai cilvēks un AI kopā strādā ar vienu kodu: viens raksta, otrs pārbauda.","also":["darbs pārī","pairing"]},{"id":"docs","g":"build","word":"Dokumentācija","text":"Rakstiski skaidrojumi par to, kā kaut kas darbojas vai kā to lietot.","also":["dokumentācija","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Pirmais fails, kas repozitorijā jāizlasa: kas ir projekts un kā to palaist.","also":["README faili","READMEs"]},{"id":"legacy","g":"build","word":"Mantotā sistēma","text":"Vecāka sistēma, kas joprojām tiek izmantota, bet ir grūti maināma, bieži tāpēc, ka maz cilvēku to vēl saprot.","also":["mantotās sistēmas","mantotais kods","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Tehniskais parāds","text":"Īsceļi, kas tagad ietaupa laiku, bet vēlāk palēnina izmaiņas, kā aizdevums ar augošiem procentiem. Refaktorēšana to samazina.","also":["tech debt"]},{"id":"test","g":"test","word":"Tests","text":"Pārbaude, vai kaut kas darbojas pareizi. Dažus testus dators veic pats pēc katras koda izmaiņas; citus veic tu, izmēģinot pabeigtu kartīti pirms pieņemšanas.","also":["testi","testa","testu","testam","testēt","testēšanai","testēšana","testējami","testējams","jātestē"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kvalitātes nodrošināšana: viss, ko dara, lai pirms ieviešanas pārbaudītu darba pareizību. AI-gile QA nozīmē automātiskās pārbaudes: sarkans QA rāda kļūmi, un ieviešana gaida tās novēršanu.","also":["kvalitātes pārbaudes","kvalitātes pārbaude"]},{"id":"testpile","g":"test","word":"Testu kaudze","text":"Pabeigtās kartītes, kas gaida, lai tu tās izmēģinātu, cita pēc citas. Pieņem vienu vai sūti to atpakaļ ar piezīmi, un parādās nākamā.","also":["testu kaudzes","testu kaudzi","testu kaudzē"]},{"id":"autotest","g":"test","word":"Automatizēts tests","text":"Pārbaude, ko dators pats veic pēc katras koda izmaiņas, lai agri pamanītu kļūdas.","also":["automatizēti testi","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manuāls tests","text":"Cilvēks pats izmēģina darbu, lai pārbaudītu, vai tas darbojas pareizi.","also":["manuāli testi","manuāla testēšana","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Vienībtests","text":"Neliela automātiska pārbaude vienai sīkai koda daļai atsevišķi.","also":["vienībtesti","unit tests"]},{"id":"integtest","g":"test","word":"Integrācijas tests","text":"Pārbaude, vai vairākas daļas pareizi darbojas kopā, nevis tikai katra atsevišķi.","also":["integrācijas testi","integration tests"]},{"id":"endtoend","g":"test","word":"Pilna cikla tests (E2E)","text":"Tests, kas no sākuma līdz beigām rīkojas kā īsts lietotājs, piemēram, reģistrējas, iepērkas un samaksā.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Lietotāju pieņemšanas testēšana (UAT)","text":"Darba pasūtītāji paši to izmēģina un pasaka, vai tas atbilst vajadzībām. AI-gile testu kaudze ir tā versija.","also":["UAT","pieņemšanas testēšana","acceptance testing"]},{"id":"regression","g":"test","word":"Regresija","text":"Tas, kas agrāk darbojās, pēc izmaiņas vairs nedarbojas. Regresijas testi pārbauda, vai vecās iespējas joprojām strādā.","also":["regresijas","regresijas tests","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Dūmu tests","text":"Ļoti ātra pārbaude, vai galvenās lietas vispār darbojas, piemēram, tūlīt pēc izmaiņas ieviešanas. Ja tā neizdodas, apstājies un izpēti.","also":["dūmu testi","smoke tests"]},{"id":"exploratory","g":"test","word":"Izpētes testēšana","text":"Brīva produkta izmēģināšana dažādos veidos, meklējot problēmas, ko plānotās pārbaudes varētu nepamanīt.","also":["izpētes tests","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Testa gadījums","text":"Viens pierakstīts izmēģināšanas scenārijs: soļi un paredzamais iznākums.","also":["testa gadījumi","test cases"]},{"id":"coverage","g":"test","word":"Testu pārklājums","text":"Cik lielu koda daļu pārbauda automātiskie testi. Vairāk parasti ir drošāk, bet liels pārklājums vien nepierāda labu darbību.","also":["koda pārklājums","code coverage"]},{"id":"testdata","g":"test","word":"Testa dati","text":"Izdomāta parauginformācija testēšanai, lai neatklātu īstu cilvēku privātos datus.","also":["testa datu sagataves","test fixtures"]},{"id":"edgecase","g":"test","word":"Robežgadījums","text":"Neparasta situācija pie iespēju robežām, piemēram, tukša veidlapa vai vārds ar apostrofu, kur bieži rodas kļūdas.","also":["robežgadījumi","edge cases"]},{"id":"happypath","g":"test","word":"Veiksmīgais scenārijs","text":"Parastais ceļš, kur viss izdodas. Laba testēšana pārbauda arī neveiksmīgos scenārijus."},{"id":"perftest","g":"test","word":"Veiktspējas testēšana","text":"Pārbaude, cik ātri kaut kas darbojas un cik labi iztur slodzi.","also":["veiktspējas tests","veiktspējas testi","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Slodzes testēšana","text":"Pārbaude, kā sistēma darbojas, kad to vienlaikus lieto daudz cilvēku.","also":["slodzes tests","slodzes testi","load test","load tests"]},{"id":"sectest","g":"test","word":"Drošības testēšana","text":"Vājumu meklēšana, kas ļautu ļaunprātīgi izmantot sistēmu vai redzēt to, ko nedrīkstētu.","also":["drošības tests","drošības testi","security test","security tests"]},{"id":"accesstest","g":"test","word":"Piekļūstamības testēšana","text":"Pārbaude, vai produktu var lietot cilvēki ar dažādām spējām, arī ar ekrāna lasītāju vai tikai tastatūru.","also":["piekļūstamības tests","accessibility test"]},{"id":"linting","g":"test","word":"Koda stila pārbaude","text":"Automātiska pārbaude, kas pamana iespējamas kļūdas un nekārtīgu koda stilu, līdzīgi programmu pareizrakstības pārbaudei.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statiskā analīze","text":"Koda automātiska lasīšana problēmu meklēšanai, to nepalaižot.","also":["statiskā koda analīze","static code analysis"]},{"id":"flaky","g":"test","word":"Nestabils tests","text":"Tests, kas dažreiz izdodas un dažreiz neizdodas bez skaidra iemesla, tāpēc tam nevar pilnībā uzticēties.","also":["nestabili testi","flaky tests"]},{"id":"repro","g":"test","word":"Kļūdas atkārtošana","text":"Kļūdas apzināta atkārtošana ar tiem pašiem soļiem, lai to izpētītu un novērstu. Šo soļu apraksts ir kļūdas ziņojuma noderīgākā daļa.","also":["repro","reproduce","atkārtošanas soļi","steps to reproduce"]},{"id":"severity","g":"test","word":"Nopietnība","text":"Cik smagas ir problēmas sekas — no nelielām neērtībām līdz pilnīgai apstāšanai.","also":["nopietnības līmenis","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Jaunas programmatūras versijas kopēšana uz datoriem, kas to darbina, piemēram, testa kopijā vai īstajā pakalpojumā."},{"id":"release","g":"change","word":"Laidiens","text":"Nosaukta pabeigta darba paka, kas nonāk darbībā vienlaikus, ar īsām piezīmēm par to, kas mainījies. 🚀 Laidieni piezīmes uzraksta no izdarītajām kartītēm.","also":["laidieni","laidiena","laidienu","laidienā","laidienos","laidieniem"]},{"id":"rollback","g":"change","word":"Atgriešana","text":"Atgriešanās pie pēdējās strādājošās versijas, ja jaunā rada problēmas. AI-gile atgriešana apkopo katrai izmaiņai pierakstītos atcelšanas soļus vienā kontrolsarakstā.","also":["atgriezt","atgriešanas","atgriešanu","atgrieza","atgriezts"]},{"id":"live","g":"change","word":"Darbībā","text":"Īstā versija, ko cilvēki lieto, pretstatā kopijai, kurā izmēģina lietas. Izstrādātāji to sauc arī par produkciju.","also":["produkcija","produkcijā","produkcijas"],"noTip":1},{"id":"change","g":"change","word":"Izmaiņa","text":"Plānota izmaiņa kaut kam, uz ko cilvēki paļaujas, iepriekš pierakstīta: kas, kāpēc, risks, kad un kā to atcelt. Sāc ar 🔀 Iesniegt izmaiņu.","also":["izmaiņas","izmaiņu","izmaiņām","izmaiņu pieprasījums","izmaiņu pieprasījumi"],"noTip":1},{"id":"risk","g":"change","word":"Risks","text":"Kaut kas, kas var noiet greizi, novērtēts pēc tā, cik tas ticams un cik slikti būtu. ⚠️ Riski tos glabā vienā sarakstā, augstākais vērtējums pirmais, katram ar datumu, kad paskatīties vēlreiz.","also":["riski","riska","risku","riskiem","risku reģistrs"]},{"id":"chgwin","g":"change","word":"Izmaiņu logs","text":"Laiki, kad izmaiņas drīkst nonākt darbībā, piemēram, mierīgs otrdienas vakars. Ārpus loga izmaiņu kartīti nevar pabeigt, ja vien tā nav ārkārtas izmaiņa.","also":["izmaiņu logi","izmaiņu loga","izmaiņu logā","izmaiņu logus"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Pēdējā pārbaude tieši pirms ieviešanas: katrs apstiprinātājs saka „Go” vai „No go”. Darbs turpinās tikai tad, ja visi saka „Go”.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Apstiprinājums","text":"Gaidīšana uz „jā”, pirms darbs sākas. Kartīte, ko iesniedz draugs, vai izmaiņa gaida ✅ Apstiprinājumos, līdz tu to apstiprini vai noraidi.","also":["apstiprinājumi","apstiprinājuma","apstiprinājumu","apstiprinājumiem"]},{"id":"quiettime","g":"change","word":"Klusais laiks","text":"Laika posms, piemēram, tiešraide, demonstrācija vai nakts, kad neko neievieš; citur to sauc par izmaiņu iesaldēšanu. Komandas turpina strādāt un testēt, bet ieviešana gaida posma beigas.","also":["klusie laiki","klusā laika","klusajā laikā","izmaiņu iesaldēšana"]},{"id":"devops","g":"change","word":"DevOps","text":"Darba veids, kur programmatūras veidotāji un uzturētāji strādā kā viena komanda ar plašu automatizāciju, lai izmaiņas ieviestu bieži un droši."},{"id":"cicd","g":"change","word":"CI/CD (nepārtraukta integrācija un piegāde)","text":"Visu dalībnieku izmaiņas bieži apvieno galvenajā versijā un katru reizi automātiski pārbauda (nepārtraukta integrācija), tāpēc programmatūra vienmēr ir gatava ieviešanai ar vienu pogas spiedienu (nepārtraukta piegāde).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Nepārtraukta izvietošana","text":"Solis tālāk par nepārtrauktu piegādi: katra izmaiņa, kas iztur pārbaudes, automātiski nonāk lietošanā bez pogas nospiešanas.","also":["nepārtrauktas izvietošanas","continuous deployments"]},{"id":"pipeline","g":"change","word":"Konveijers","text":"Automātisku soļu virkne, ko izmaiņa iziet ceļā līdz lietošanai, piemēram, būvēšana, testēšana un izvietošana.","also":["konveijeri","konveijera","konveijeru","pipeline","pipelines"]},{"id":"environment","g":"change","word":"Vide","text":"Atsevišķa sistēmas kopija noteiktam mērķim, piemēram, izstrādei, testēšanai vai īstai lietošanai.","also":["vides","vidi","vidē","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Izstrādes vide","text":"Kopija, kurā izstrādātājs strādā, bieži savā datorā, kur kaut kā salaušana nevienam nekaitē.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Testēšanas vide","text":"Atsevišķa sistēmas kopija tikai testēšanai, neskarot īsto pakalpojumu.","also":["testēšanas vides","test environments"]},{"id":"staging","g":"change","word":"Pirmsprodukcijas vide","text":"Pēdējā izmēģinājuma kopija, kas izveidota tāpat kā īstā sistēma, galīgai pārbaudei pirms ieviešanas.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Būvējuma artefakts","text":"Būvēšanā radītais fails vai komplekts, kas gatavs glabāšanai, pārbaudei vai ieviešanai.","also":["būvējuma artefakti","build artifacts"]},{"id":"hotfix","g":"change","word":"Steidzams labojums","text":"Ātri ieviests ārpuskārtas labojums, jo kaut kas svarīgs nedarbojas.","also":["steidzami labojumi","steidzama labojuma","hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Ielāps","text":"Neliels atjauninājums, kas novērš kļūdu vai drošības caurumu. Drošības ielāpus svarīgi uzlikt ātri.","also":["ielāpi","ielāpa","ielāpu","drošības ielāps","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Versijas numurs","text":"Apzīmējums, piemēram, 2.4.1, kas pasaka, kurš laidiens tev ir. Bieži pirmais skaitlis mainās lielām izmaiņām, pēdējais — maziem labojumiem.","also":["versiju numuri","semantiskā versēšana","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Laidiena piezīmes","text":"Īss un saprotams laidiena izmaiņu saraksts lietotājiem, tostarp labojumi un zināmie ierobežojumi. To sauc arī par izmaiņu žurnālu.","also":["izmaiņu žurnāls","changelog","change log"]},{"id":"flag","g":"change","word":"Funkcijas slēdzis","text":"Funkcijas ieslēgšanas un izslēgšanas slēdzis, lai jauno darbu var ieviest paslēptu un vēlāk ieslēgt vai izslēgt bez jauna laidiena.","also":["funkciju slēdži","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Labošana ar jaunu versiju","text":"Neveiksmīga laidiena labošana, ātri ieviešot jaunu, izlabotu versiju, nevis atgriežoties pie vecās.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Kanārijputniņa laidiens","text":"Izmaiņu vispirms ievieš nelielai grupai un tikai pēc veiksmīgas pārbaudes — visiem. Nosaukums nāk no kanārijputniņiem, ko ogļrači ņēma pazemē agrīnai brīdināšanai par briesmām.","also":["kanārijputniņa laidieni","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Zili zaļā izvietošana","text":"Uztur divas īstās sistēmas kopijas un visus reizē pārslēdz uz jauno, lai kļūmes gadījumā varētu uzreiz pārslēgt atpakaļ.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Izvietošana bez dīkstāves","text":"Jaunas versijas ieviešana, pakalpojumam ne mirkli nepārtraucot darboties lietotājiem.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Izmaiņu nodrošināšana","text":"Palīdzība izmaiņu veiksmīgai ieviešanai: riska izvērtēšana, vajadzīgais apstiprinājums un laba laika izvēle. To sauc arī par izmaiņu pārvaldību.","also":["izmaiņu pārvaldība","change management"]},{"id":"cab","g":"change","word":"Izmaiņu konsultatīvā padome (CAB)","text":"Grupa, kas pārskata svarīgas izmaiņas un vienojas, vai un kad tās drīkst īstenot.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standarta izmaiņa","text":"Zema riska izmaiņa, ko katru reizi veic vienādi pārbaudītā veidā, tāpēc tā apstiprināta iepriekš.","also":["standarta izmaiņas","standard changes"]},{"id":"normchange","g":"change","word":"Parasta izmaiņa","text":"Izmaiņa, kas pirms īstenošanas jāpārbauda un jāapstiprina.","also":["parastas izmaiņas","normal changes"]},{"id":"emergchange","g":"change","word":"Ārkārtas izmaiņa","text":"Izmaiņa, kas jāveic nekavējoties, lai novērstu vai nepieļautu nopietnas problēmas, ar attiecīgi ātrāku apstiprināšanu.","also":["ārkārtas izmaiņas","emergency changes"]},{"id":"automation","g":"change","word":"Automatizācija","text":"Atkārtota darba uzticēšana datoram, lai tas notiktu ātrāk un katru reizi vienādi.","also":["automatizēts","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktūra","text":"Ierīces, tīkli un pakalpojumi, uz kuriem darbojas programmatūra.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastruktūra kā kods (IaC)","text":"Serveru un iestatījumu aprakstīšana failos blakus kodam, lai tos katru reizi varētu atjaunot tieši tāpat.","also":["IaC"]},{"id":"cloud","g":"change","word":"Mākonis","text":"Datoru, krātuves un pakalpojumu noma no liela piegādātāja internetā, nevis pašu ierīču iegāde.","also":["mākoņdatošana","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Mākoņpakalpojumu sniedzējs","text":"Uzņēmums, kas internetā iznomā skaitļošanas resursus, piemēram, Amazon Web Services (AWS), Microsoft Azure vai Google Cloud.","also":["mākoņpakalpojumu sniedzēji","cloud providers"]},{"id":"hosting","g":"change","word":"Mitināšana","text":"Vieta, kur tava lietotne vai vietne atrodas un darbojas, lai cilvēki tai piekļūtu; parasti to nomā no uzņēmuma.","also":["mitināts"]},{"id":"domain","g":"change","word":"Domēna vārds","text":"Tīmekļa adrese, ko cilvēki ieraksta, piemēram, example.com. To nomā uz gadu, tāpēc noma jāatjauno.","also":["domēna vārdi","domēns","domēna","domēnu","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Interneta adrešu grāmata, kas nosaukumu, piemēram, example.com, pārvērš pareizā datora adresē. Saīsinājums nozīmē domēnu nosaukumu sistēmu.","also":["domēnu nosaukumu sistēma","domain name system"]},{"id":"container","g":"change","word":"Konteiners","text":"Noslēgta pakotne ar lietotni un visu tai vajadzīgo, lai tā jebkurā datorā darbotos vienādi. Pazīstamākais rīks ir Docker.","also":["konteineri","konteinera","konteineru","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuālā mašīna (VM)","text":"Šķietams dators, kas darbojas īsta datora iekšienē, lai viena liela ierīce varētu darboties kā vairākas.","also":["VM","VMs","virtuālās mašīnas","virtual machines"]},{"id":"serverless","g":"change","word":"Bezserveru risinājums","text":"Koda palaišana bez savu serveru uzturēšanas: pakalpojuma sniedzējs to darbina pēc vajadzības, un tu maksā par izmantoto."},{"id":"lb","g":"change","word":"Slodzes līdzsvarotājs","text":"Risinājums, kas sadala apmeklētājus starp vairākiem serveriem, lai neviens netiktu pārslogots.","also":["slodzes līdzsvarotāji","load balancers"]},{"id":"cache","g":"change","word":"Kešatmiņa","text":"Tuvumā glabāti neseni rezultāti, lai to pašu nevajadzētu iegūt vai aprēķināt vēlreiz. Iztīrīšana var palīdzēt, ja lapa rāda novecojušu saturu.","also":["kešatmiņas","kešatmiņu","kešatmiņā","kešošana","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Satura piegādes tīkls (CDN)","text":"Vispasaules serveru kopums, kas glabā lapu un attēlu kopijas apmeklētāju tuvumā, lai tie ātri ielādētos.","also":["CDN"]},{"id":"migration","g":"change","word":"Migrācija","text":"Datu vai sistēmu pārcelšana no veca risinājuma uz jaunu vai rūpīga datubāzes uzbūves maiņa.","also":["migrācijas","datubāzes migrācija","migrations","database migration"]},{"id":"service","g":"run","word":"Pakalpojums","text":"Kaut kas, ko tu uzbūvēji un uz ko cilvēki paļaujas, piemēram, tīmekļa vietne vai lietotne, un par ko rūpējas, lai tas turpinātu strādāt. Atzīmē „Šis projekts ir pakalpojums” un norādi, ko tas piedāvā, kas to lieto un kas dežurē.","also":["pakalpojumi","pakalpojuma","pakalpojumu","pakalpojumam","pakalpojumā","pakalpojumiem"]},{"id":"uptimepct","g":"run","word":"Darbspējas laiks","text":"Cik lielu laika daļu pakalpojums darbojas, parasti procentos. Arī 99,9% pieļauj apmēram 43 minūšu dīkstāvi mēnesī.","also":["darbspējas procentuālā daļa","uptime percentage"]},{"id":"uptime","g":"run","word":"Pieejamības pārbaude","text":"Automātiska pārbaude ik pēc dažām minūtēm, vai tavs pakalpojums vēl atbild. Ja tā vairākas reizes pēc kārtas neizdodas, AI-gile pats atver incidenta kartīti.","also":["pieejamības pārbaudes","pieejamības pārbaudi","darbspējas pārbaudes","uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Statusa lapa","text":"Publiska lapa, kas rāda, vai pakalpojums strādā (zaļš, oranžs vai sarkans), ar jaunāko ziņu, lai cilvēki, kas to lieto, varētu paskatīties, nevis jautāt.","also":["statusa lapas","statusa lapā","statusa lapu"]},{"id":"desk","g":"run","word":"Pakalpojumu galds","text":"Vieta, kur ienāk jautājumi un ziņojumi no cilvēkiem, kas lieto tavu pakalpojumu. AI-gile katru sakārto kā pieprasījumu, incidentu vai ideju un pasaka, ja tas izskatās pēc kaut kā jau ziņota.","also":["pakalpojumu galdi","palīdzības dienests","atbalsta galds"]},{"id":"svcrequest","g":"run","word":"Pakalpojuma pieprasījums","text":"Kāds lūdz kaut ko ikdienišķu, piemēram, jaunu kontu vai nelielu palīdzību, nevis ziņo, ka kaut kas ir salūzis. Tas gaida savu kārtu; incidents iet pirmais.","also":["pakalpojumu pieprasījumi"]},{"id":"incident","g":"run","word":"Incidents","text":"Kaut kas pašlaik lietotājiem ir bojāts vai nedarbojas pareizi, piemēram, vietne nav pieejama vai ir ļoti lēna. 🔥 incidenta kartīte apiet rindu: darbības atjaunošana ir pirmajā vietā.","also":["incidenti","incidenta","incidentu","incidentam","incidentiem","incidentā"]},{"id":"major","g":"run","word":"Liels incidents","text":"Liels incidents: skarti daudzi cilvēki vai apdraudēta nauda vai dati. Viena poga liek visām komandām pie tā strādāt (spiets), pamodina dežurējošo un ik pēc 30 minūtēm prasa statusa ziņu.","also":["lieli incidenti","liela incidenta","lielu incidentu","lielā incidentā"]},{"id":"oncall","g":"run","word":"Dežūra","text":"Būt tam, kas atbild, kad kaut kas salūst, pat naktī. Katram pakalpojumam ir dežurējošs komandas dalībnieks, ko pamodina pirmo, kad notiek tā incidents.","also":["dežurē","dežurējošais","dežurējošo","dežūrā","dežūras","on-call"]},{"id":"replyby","g":"run","word":"Atbildes termiņš","text":"Cik ilgi kartīte drīkst gaidīt pirmo atbildi, piemēram, stundu incidentam. Pēc tam tā saņem sarkanu pulksteni, lai nekas netiktu klusi aizmirsts. To sauc arī par reakcijas mērķi.","also":["atbildes termiņi","atbildes termiņa","atbildes termiņu","reakcijas mērķis","reakcijas mērķi"]},{"id":"postmortem","g":"run","word":"Pēcanalīze","text":"Īss atskats pēc incidenta: kas notika, kas palīdzēja un ko mainīt, nevienu nevainojot. Incidentu nevar aizvērt bez tās.","also":["pēcanalīzes","pēcanalīzi","pēcanalīzē","post-mortem","postmortem","pēcincidenta pārskats"]},{"id":"problem","g":"run","word":"Problēma","text":"Apslēptais cēlonis vienam vai vairākiem incidentiem. 🧩 Problēmas kartīte sagrupē incidentus, kas atkārtojas, lai cēloni atrastu un salabotu uz visiem laikiem.","also":["problēmas","problēmu","problēmai","problēmām"],"noTip":1},{"id":"rootcause","g":"run","word":"Pamatcēlonis","text":"Īstais iemesls, kāpēc kaut kas salūza, nevis tikai tas, ko redzēji noejam greizi. Salabo pamatcēloni, un incidents vairs neatkārtojas.","also":["pamatcēloņi","pamatcēloņa","pamatcēloni","pamatcēloņus"]},{"id":"workaround","g":"run","word":"Apiešanas risinājums","text":"Veids, kā uzturēt lietas darbībā, līdz īstais labojums ir gatavs, piemēram, kaut ko restartēt, kad tas iestrēgst. To pieraksta problēmas kartītē, lai nevienam tas nav jāizdomā no jauna.","also":["apiešanas risinājumi","apiešanas risinājuma","apiešanas risinājumu","pagaidu risinājums"]},{"id":"knownerror","g":"run","word":"Zināmā kļūda","text":"Problēma ar zināmu cēloni, kas vēl nav novērsta, parasti ar pierakstītu apiešanas risinājumu. 🧩 Zināmās kļūdas tās uzskaita, lai visi izmantotu apiešanas risinājumu, nevis pētītu no jauna.","also":["zināmās kļūdas","zināmo kļūdu","zināma kļūda","zināmām kļūdām"]},{"id":"runbook","g":"run","word":"Runbook","text":"Soli pa solim instrukcija, kā salabot zināma veida nepatikšanas, lai tas katru reizi tiktu izdarīts vienādi un ātri. Pēc liela incidenta komanda var to ierosināt, un tu dod savu OK.","also":["runbooks","runbook"]},{"id":"ci","g":"run","word":"Konfigurācijas vienība","text":"Viena lieta, no kuras atkarīgs tavs pakalpojums, piemēram, serveris, domēns, sertifikāts, atslēga vai piegādātājs. 🗂️ Konfigurācijas vienības tās uzskaita katram pakalpojumam, lai redzētu, ko incidents ietekmē un kam vajag atjaunošanu vai dublējumu.","also":["konfigurācijas vienības"]},{"id":"expiry","g":"run","word":"Derīguma termiņš","text":"Datums, kad kaut kas bez atjaunošanas vairs nedarbosies, piemēram, vietnes drošības sertifikāts vai domēns. AI-gile vēro šos datumus un katram izveido vienu atjaunošanas kartīti 30 dienas iepriekš, lai nekas neapstātos negaidīti.","also":["derīguma termiņi","termiņu uzraudzība"]},{"id":"backup","g":"run","word":"Dublējums","text":"Saglabāta tavu datu kopija no agrāka laika, uz ko paļauties, ja kaut kas pazūd vai sabojājas. AI-gile katru dienu izveido tavu dēļu dublējumu.","also":["dublējumi","dublējuma","dublējumu","dublējumā","dublējumiem","rezerves kopija"]},{"id":"restore","g":"run","word":"Atjaunošana","text":"Datu atlikšana atpakaļ no dublējuma. Dublējums patiesi skaitās tikai tad, kad zini, ka to var atjaunot, tāpēc ik pa laikam vērts pamēģināt.","also":["atjaunot","atjaunots","atjaunoti","atjaunošanu"]},{"id":"svcreview","g":"run","word":"Pakalpojuma pārskats","text":"Atskats uz viena pakalpojuma mēnesi: atvērtie un salabotie incidenti, cik ātri cilvēki saņēma atbildi, pieejamība un izlietotie tokeni. Ikmēneša pārskats to rāda katram pakalpojumam.","also":["pakalpojumu pārskati","ikmēneša pārskats","ikmēneša pārskati"]},{"id":"accessreview","g":"run","word":"Piekļuves pārskats","text":"Ik pēc 90 dienām pārbauda, kam vēl ir piekļuve: kopīgošanas saitēm, draugu lomām un saglabātām parolēm un atslēgām. Katru saglabā vai noņem, lai veca piekļuve nepaliktu spēkā.","also":["piekļuves pārskati"]},{"id":"improvements","g":"run","word":"Uzlabojumu saraksts","text":"Viss, ko komanda nolēma uzlabot, vienuviet: retro ieteikumi, pārskatu darbības un problēmu labojumi, katram ar savu statusu. Atrodams sadaļā 📈 Uzlabojumi.","also":["uzlabojumu saraksti","uzlabojumi"]},{"id":"tokencap","g":"run","word":"Tokenu limits","text":"Ikmēneša limits tokeniem, ko pakalpojuma aģenti drīkst izmantot. Pie 80% tu saņem brīdinājumu; pie 100% to fona darbs gaida līdz nākamajam mēnesim vai līdz tu paaugstini limitu.","also":["tokenu limiti"]},{"id":"svcmgmt","g":"run","word":"Pakalpojumu pārvaldība","text":"Viss, kas vajadzīgs, lai pakalpojums ik dienu būtu noderīgs un darbotos cilvēkiem, kas uz to paļaujas.","also":["pakalpojuma pārvaldīšana"]},{"id":"itil","g":"run","word":"ITIL","text":"Plaši izmantotas vadlīnijas labai pakalpojumu pārvaldībai, kas aptver incidentus, problēmas un izmaiņas. Nosaukums sākotnēji nozīmēja IT infrastruktūras bibliotēku."},{"id":"itsm","g":"run","word":"IT pakalpojumu pārvaldība (ITSM)","text":"Tehnoloģiju nodrošināšana cilvēkiem kā pakalpojums ar skaidru kārtību pieprasījumiem, incidentiem, izmaiņām un uzlabojumiem.","also":["ITSM"]},{"id":"managed","g":"run","word":"Pārvaldīts pakalpojums","text":"Pakalpojums, ko tavā vietā darbina un uztur kāds cits saskaņā ar vienošanos par tā kvalitāti.","also":["pārvaldīti pakalpojumi","managed services"]},{"id":"svcowner","g":"run","word":"Pakalpojuma īpašnieks","text":"Cilvēks, kas atbild par pakalpojumu kopumā: tā darbību, izmaksām un uzlabojumiem.","also":["pakalpojumu īpašnieki","service owners"]},{"id":"sla","g":"run","word":"Pakalpojuma līmeņa vienošanās (SLA)","text":"Rakstisks solījums klientiem par pakalpojuma kvalitāti, piemēram, „pieejams 99,9% laika” vai „atbilde stundas laikā”, bieži ar atlīdzību solījuma neizpildes gadījumā.","also":["SLA","SLAs","pakalpojuma līmeņa vienošanās","service level agreement"]},{"id":"slo","g":"run","word":"Pakalpojuma līmeņa mērķis (SLO)","text":"Komandas pašu mērķis pakalpojuma darbībai noteiktā laikā, parasti drošības pēc nedaudz stingrāks par SLA.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Pakalpojuma līmeņa rādītājs (SLI)","text":"Faktiskais mērījums, ko salīdzini ar mērķi, piemēram, veiksmīgi ielādētu apmeklējumu īpatsvars.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Pieejamība","text":"Vai cilvēki pakalpojumu var izmantot, kad tas vajadzīgs; bieži to mēra ar darbspējas laiku.","also":["augsta pieejamība","high availability"]},{"id":"downtime","g":"run","word":"Dīkstāve","text":"Laiks, kad pakalpojums nedarbojas vai ir izslēgts, plānoti vai neplānoti.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Kļūdu budžets","text":"Nelielais kļūmju apjoms, ko pieļauj uzticamības mērķis. Kamēr tas atlicis, vari riskēt ar izmaiņām; kad iztērēts, tempu samazina.","also":["kļūdu budžeti","error budgets"]},{"id":"outage","g":"run","word":"Pārtraukums","text":"Laiks, kad pakalpojums lietotājiem nav pieejams vai ir nopietni bojāts.","also":["outages"]},{"id":"degraded","g":"run","word":"Pasliktināta darbība","text":"Darbojas, bet slikti: lēni vai ar atsevišķām nestrādājošām daļām.","also":["pasliktināts pakalpojums","degraded service"]},{"id":"monitoring","g":"run","word":"Uzraudzība","text":"Nepārtraukta automātiska pakalpojuma vērošana, lai pamanītu problēmas, vēlams pirms lietotājiem."},{"id":"observability","g":"run","word":"Novērojamība","text":"Cik labi no ārpuses vari saprast sistēmā notiekošo, izmantojot tās žurnālus, skaitļus un pieprasījumu ceļus.","also":["o11y"]},{"id":"log","g":"run","word":"Žurnāls","text":"Programmas pastāvīgi veidota darbību dienasgrāmata, kas palīdz noskaidrot, kas nogāja greizi.","also":["žurnāli","žurnāla","žurnālu","žurnālā","žurnalēšana","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Pieprasījuma trase","text":"Ieraksts par viena pieprasījuma ceļu caur sistēmas daļām soli pa solim, parādot palēninājuma vietas.","also":["trasēšana","traces","tracing"]},{"id":"latency","g":"run","word":"Latentums","text":"Atbildei vajadzīgais laiks, piemēram, gaidīšana starp klikšķi un lapas parādīšanos."},{"id":"alert","g":"run","word":"Brīdinājums","text":"Automātisks ziņojums, ka kaut kam jāpievērš uzmanība, piemēram, vietne neatbild.","also":["brīdinājumi","brīdinājuma","brīdinājumu","brīdināšana","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Brīdinājumu nogurums","text":"Kad brīdinājumu ir tik daudz, ka cilvēki sāk tos ignorēt, arī svarīgos.","also":["trauksmju nogurums","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Informācijas panelis","text":"Ekrāns, kur vienā acu uzmetienā redzami svarīgākie skaitļi un stāvokļi.","also":["informācijas paneļi","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Dežuranta izsaukšana","text":"Steidzama dežuranta izsaukšana vai modināšana problēmas dēļ.","also":["paged"]},{"id":"escalation","g":"run","word":"Eskalācija","text":"Prasmīgāka vai pilnvarotāka cilvēka iesaistīšana, ja problēmu pašreizējā līmenī nevar atrisināt vai nevar pietiekami ātri.","also":["eskalēt","eskalēts","escalate","escalated"]},{"id":"triage","g":"run","word":"Sākotnējā šķirošana","text":"Ienākošo problēmu ātra sakārtošana pēc steidzamības un svarīguma, lai vispirms risinātu smagākās.","also":["triaged"]},{"id":"impact","g":"run","word":"Ietekme","text":"Cik lielā mērā kaut kas ietekmē cilvēkus: cik daudzus un cik smagi.","noTip":1},{"id":"urgency","g":"run","word":"Steidzamība","text":"Cik ātri kaut kas jārisina. Ietekme un steidzamība kopā nosaka prioritāti.","noTip":1},{"id":"plevels","g":"run","word":"Prioritātes līmeņi (P1, P2…)","text":"Apzīmējumi problēmas steidzamībai. P1 ir visnopietnākais un prasa tūlītēju rīcību.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Pieteikumu rinda","text":"Pieprasījumi un incidenti, kas gaida, kad kāds tos uzņemsies.","also":["pieteikumu rindas","ticket queues"]},{"id":"tiers","g":"run","word":"Pirmā un otrā atbalsta līnija","text":"Atbalsta līmeņi: pirmā līnija saņem zvanu un labo vienkāršās lietas; otrajai ir dziļākas prasmes grūtākiem gadījumiem. Tos sauc arī par 1. un 2. līmeni.","also":["pirmā līnija","otrā līnija","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incidenta vadītājs","text":"Viens cilvēks, kas vada incidenta risināšanu, lai visi zinātu, kurš lemj un kurš ko dara.","also":["incidentu vadītāji","incident commanders"]},{"id":"responsetime","g":"run","word":"Reaģēšanas laiks","text":"Laiks līdz brīdim, kad kāds pirmoreiz uzņemas pieprasījumu vai incidentu.","also":["reaģēšanas laiki","response times"]},{"id":"resolution","g":"run","word":"Atrisināšanas laiks","text":"Laiks no pieprasījuma vai incidenta paziņošanas līdz pilnīgai atrisināšanai.","also":["atrisināšanas laiki","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Vidējais atjaunošanas laiks (MTTR)","text":"Vidējais laiks pakalpojuma darbības atjaunošanai pēc kļūmes. MTTR var nozīmēt nedaudz atšķirīgas lietas, tāpēc pasaki, ko mēri.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Vidējais laiks starp kļūmēm (MTBF)","text":"Cik ilgi pakalpojums vidēji darbojas, pirms kaut kas salūst.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Konfigurācijas pārvaldības datubāze (CMDB)","text":"Visu konfigurācijas vienumu un to savienojumu saraksts, lai redzētu, kas no kā ir atkarīgs.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aktīvs","text":"Jebkas vērtīgs, kas tev pieder vai par ko maksā pakalpojuma darbībai, piemēram, klēpjdators, programmatūras licence vai domēns.","also":["aktīvi","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Jaudas plānošana","text":"Nodrošināšana, ka nākotnes vajadzībām pietiks skaitļošanas jaudas, krātuves un cilvēku.","also":["jaudas plāns","capacity plan"]},{"id":"scaling","g":"run","word":"Mērogošana","text":"Lielāka lietotāju skaita apkalpošana, palielinot ierīces jaudu (vertikālā mērogošana) vai pievienojot vairāk ierīču (horizontālā mērogošana).","also":["vertikāla mērogošana","horizontāla mērogošana","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Darbības nepārtrauktība","text":"Plāni svarīgā darba turpināšanai nopietnu problēmu gadījumā, piemēram, zaudējot biroju, svarīgu piegādātāju vai datorus.","also":["darbības nepārtrauktības plāns","business continuity plan"]},{"id":"dr","g":"run","word":"Atkopšana pēc katastrofas (DR)","text":"Plāns un rīki pakalpojuma atjaunošanai pēc nopietna notikuma, piemēram, vesela datu centra zaudēšanas.","also":["katastrofu atkopšana","disaster recovery"]},{"id":"rto","g":"run","word":"Atjaunošanas laika mērķis (RTO)","text":"Ilgākais laiks, ko pakalpojums pēc katastrofas drīkst nedarboties, pirms tam jābūt atjaunotam.","also":["RTO"]},{"id":"rpo","g":"run","word":"Atjaunošanas punkta mērķis (RPO)","text":"Cik daudz jaunāko datu drīkstētu zaudēt, mērot laikā. Vienas stundas RPO nozīmē rezerves kopijas vismaz reizi stundā.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Dublēšana","text":"Gatavas rezerves, piemēram, otrs serveris, lai viena kļūme neapturētu pakalpojumu.","also":["rezerves elementi"]},{"id":"failover","g":"run","word":"Automātiska pārslēgšanās uz rezervi","text":"Automātiska pāreja uz rezerves sistēmu, kad parastā pārstāj darboties.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Vienīgais atteices punkts","text":"Viena daļa, kuras bojājums aptur visu sistēmu, jo nav rezerves.","also":["vienīgie atteices punkti","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Apkopes logs","text":"Plānots un lietotājiem iepriekš paziņots laiks, kad apkopes dēļ pakalpojums var būt apturēts vai lēns.","also":["apkopes logi","plānota apkope","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Nodošana","text":"Darba, zināšanu un atbildības nodošana citam cilvēkam vai komandai, lai nekas nepaliktu novārtā.","also":["handovers"]},{"id":"kb","g":"run","word":"Zināšanu bāze","text":"Palīdzības rakstu un atbilžu kopums lietotājiem un komandai.","also":["zināšanu bāzes","knowledge bases"]},{"id":"csat","g":"run","word":"Klientu apmierinātība (CSAT)","text":"Lietotāju vērtējums par apmierinātību, ko bieži prasa pēc pieteikuma slēgšanas.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Piegādātājs","text":"Ārējs uzņēmums, uz kuru paļaujies, piemēram, mitināšanas pakalpojuma sniedzējs. To sauc arī par pārdevēju vai trešo pusi.","also":["piegādātāji","pakalpojuma sniedzējs","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Pakalpojuma izbeigšana","text":"Pakalpojuma droša un galīga izslēgšana: lietotāju informēšana, datu un piekļuves sakārtošana un izmaksu apturēšana.","also":["pakalpojuma slēgšana","retiring a service"]},{"id":"eol","g":"run","word":"Dzīves cikla beigas (EOL)","text":"Brīdis, kad ražotājs vairs nepiedāvā produkta atjauninājumus vai atbalstu, tāpēc tas jāaizstāj.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Kiberdrošība","text":"Sistēmu un datu aizsargāšana pret ielaušanos, zādzību vai bojāšanu.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Autentifikācija","text":"Pārbaude, kas cilvēks ir, parasti ar paroli vai kodu. Bieži saīsina kā authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Autorizācija","text":"Pārbaude, ko cilvēks drīkst darīt, kad zināms, kas viņš ir. Bieži saīsina kā authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Daudzfaktoru autentifikācija (MFA)","text":"Pierakstīšanās ar diviem vai vairākiem pierādījumiem, piemēram, paroli un kodu tālrunī. To sauc arī par divfaktoru autentifikāciju (2FA).","also":["MFA","2FA","divfaktoru autentifikācija","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Vienotā pierakstīšanās (SSO)","text":"Viena pierakstīšanās dod piekļuvi daudzām sistēmām, piemēram, visur izmantojot darba kontu.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Paroļu pārvaldnieks","text":"Lietotne, kas izveido drošas paroles un atceras tās tavā vietā.","also":["paroļu pārvaldnieki","password managers"]},{"id":"secret","g":"sec","word":"Noslēpums","text":"Parole, atslēga vai cits privāts kods, ar ko programma kaut kam piekļūst. To nekad nedrīkst kopīgot vai ierakstīt kodā.","also":["noslēpumi","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API atslēga","text":"Slepens kods, kas ļauj programmai izmantot cita pakalpojuma API un norāda, kurš to izmanto un apmaksā.","also":["API atslēgas","API keys"]},{"id":"accesstoken","g":"sec","word":"Piekļuves pilnvara","text":"Pagaidu caurlaide, kas apliecina programmas piekļuves tiesības, lai katru reizi nevajadzētu paroli. Tā nav tas pats, kas AI tokens.","also":["piekļuves pilnvaras","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Šifrēšana","text":"Informācijas pārveidošana tā, lai to varētu izlasīt tikai ar pareizo atslēgu.","also":["šifrēts","šifrēt","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Drošs tīmekļa lapu pārsūtīšanas veids, ko rāda slēdzene pārlūkā, lai starpnieki nevarētu lapas lasīt vai mainīt."},{"id":"cert","g":"sec","word":"SSL/TLS sertifikāts","text":"Digitāla apliecība, ar kuru vietne pierāda savu identitāti un izmanto HTTPS. Tai beidzas derīgums, tāpēc tā jāatjauno.","also":["TLS sertifikāts","SSL sertifikāts","sertifikāts","sertifikāti","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Atļaujas","text":"Noteikumi par to, kurš ko drīkst redzēt vai mainīt.","also":["atļauja","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mazāko privilēģiju princips","text":"Katram cilvēkam vai programmai piešķir tikai patiešām nepieciešamo piekļuvi un tikai uz vajadzīgo laiku.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Lomās balstīta piekļuves kontrole (RBAC)","text":"Piekļuves piešķiršana pēc lomas, piemēram, skatītājs vai redaktors, nevis katram cilvēkam atsevišķi.","also":["RBAC","lomās balstīta piekļuve","role-based access"]},{"id":"vuln","g":"sec","word":"Ievainojamība","text":"Vājā vieta, ko kāds varētu izmantot, lai ielauztos vai nodarītu kaitējumu.","also":["ievainojamības","ievainojamību","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Nulles dienas ievainojamība","text":"Vājums, ko uzbrucēji zina, pirms veidotājiem bijis laiks to novērst.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Ļaunprogrammatūra","text":"Kaitīga programmatūra, piemēram, vīrusi, kas radīti bojāšanai, izspiegošanai vai zagšanai."},{"id":"ransomware","g":"sec","word":"Izspiedējprogrammatūra","text":"Ļaunprogrammatūra, kas nobloķē failus un prasa naudu par atbloķēšanu. Labas rezerves kopijas ir labākā aizsardzība.","also":["izspiedējprogrammatūras uzbrukums","ransomware attack"]},{"id":"phishing","g":"sec","word":"Pikšķerēšana","text":"Viltoti ziņojumi, kas mēģina izkrāpt paroles vai naudu vai pierunāt atvērt ko kaitīgu.","also":["pikšķerēšanas vēstule","pikšķerēšanas vēstules","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Sociālā inženierija","text":"Cilvēku, nevis datoru apmānīšana, lai iegūtu piekļuvi, piemēram, viltots zvans no „IT atbalsta”."},{"id":"firewall","g":"sec","word":"Ugunsmūris","text":"Sargs, kas izlemj, kāda tīkla datplūsma drīkst ienākt vai iziet.","also":["ugunsmūri","ugunsmūra","ugunsmūrī","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Privāts, šifrēts savienojums internetā, ko bieži izmanto drošai piekļuvei darba sistēmām.","also":["virtuālais privātais tīkls","virtual private network"]},{"id":"ddos","g":"sec","word":"Pakalpojuma atteices uzbrukums (DoS, DDoS)","text":"Pakalpojuma pārpludināšana ar viltus datplūsmu, lai īsti cilvēki to nevarētu izmantot. DDoS nozīmē, ka plūsma nāk vienlaikus no daudziem datoriem.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Ielaušanās tests","text":"Uzticamu speciālistu nolīgšana ielaušanās mēģinājumam, lai vājās vietas atrastu pirms īstiem uzbrucējiem.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Drošības audits","text":"Rūpīga aizsardzības pārbaude pēc labās prakses saraksta.","also":["drošības auditi","security audits"]},{"id":"threatmodel","g":"sec","word":"Draudu modelēšana","text":"Pārdomāšana, kas varētu uzbrukt, kā un ko tu darītu, lai to apturētu.","also":["draudu modelis","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Datu aizsardzības pārkāpums","text":"Privāta informācija nonāk pie nepiederošajiem vai tiek zaudēta vai mainīta bez atļaujas.","also":["datu aizsardzības pārkāpumi","datu noplūde","datu noplūdes","data breaches"]},{"id":"pii","g":"sec","word":"Personas dati","text":"Jebkura informācija par identificējamu cilvēku, piemēram, vārds, e-pasta adrese vai atrašanās vieta. Angliski arī PII.","also":["PII","personu identificējoša informācija","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"VDAR (GDPR)","text":"Eiropas tiesību akts par personas datiem; Apvienotajai Karalistei ir sava versija. Vāc tikai vajadzīgo, glabā droši un ļauj cilvēkiem apskatīt vai dzēst savus datus.","also":["Vispārīgā datu aizsardzības regula","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Datu aizsardzība","text":"Pareiza un likumīga rūpēšanās par personas datiem.","also":["datu aizsardzības likums","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privātuma politika","text":"Publiska lapa par to, kādus personas datus vāc, kāpēc un ko ar tiem dari.","also":["privātuma paziņojums","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Piekrišana","text":"Cilvēka skaidrs un brīvprātīgs „jā” viņa datu izmantošanai noteiktā veidā. To var atsaukt jebkurā laikā.","also":["brīvprātīga piekrišana","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Sīkdatne","text":"Neliels fails, ko vietne saglabā pārlūkā, lai atcerētos, piemēram, pierakstīšanos. Dažām vispirms vajadzīga piekrišana.","also":["sīkdatnes","sīkdatni","sīkdatņu","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Datu minimizēšana","text":"Tikai darbam patiešām vajadzīgo personas datu vākšana un glabāšana.","also":["datu samazināšana","data minimization"]},{"id":"retention","g":"sec","word":"Datu glabāšana","text":"Cik ilgi datus glabā pirms dzēšanas. Glabāt ne ilgāk par vajadzīgo ir drošāk, un bieži to prasa likums.","also":["glabāšanas termiņš","retention period"]},{"id":"anon","g":"sec","word":"Anonimizācija","text":"Datu pārveidošana tā, lai no tiem vairs nebūtu saprātīgi iespējams identificēt nevienu cilvēku.","also":["anonimizēts","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseidonimizācija","text":"Vārdu un citu datu aizstāšana ar kodiem, saistīšanas atslēgu glabājot atsevišķi. Tie joprojām ir personas dati.","also":["pseidonimizēts","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Datu apstrādes līgums (DPA)","text":"Līgums par to, kā piegādātājs tavā vārdā drīkst apstrādāt personas datus.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Novērtējums par ietekmi uz datu aizsardzību (DPIA)","text":"Rūpīga pārbaude pirms sākšanas, kā plānotā personas datu izmantošana varētu ietekmēt cilvēkus un kā mazināt riskus.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audita žurnāls","text":"Ieraksts par to, kurš ko darīja un kad, lai darbības vēlāk varētu pārbaudīt.","also":["audita žurnāli","audita pieraksti","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Atbilstība","text":"Uz tevi attiecināmo likumu, noteikumu un standartu ievērošana un spēja to pierādīt.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Pazīstams starptautisks informācijas drošības pārvaldības standarts. Uzņēmumi var saņemt sertifikātu par atbilstību tam.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"ASV ziņojums, ko pārbauda neatkarīgi auditori un kas apliecina uzņēmuma pienācīgu rūpēšanos par klientu datiem.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Aģents","text":"AI, kas patstāvīgi strādā pie uzdevuma: lasa kodu, veic izmaiņas, palaiž pārbaudes un ziņo par rezultātu. Tā darbu joprojām pārbauda.","also":["aģenti","aģenta","aģentu","aģentiem","agent","agents"]},{"id":"token","g":"ai","word":"Tokens","text":"Nelieli teksta gabali, ko AI lasa un raksta, katrs aptuveni trīs ceturtdaļas vārda. AI lietojumu skaita tokenos, tāpēc mazāks tokenu skaits atstāj vairāk plāna apjoma.","also":["tokeni","tokena","tokenu","tokeniem","token","tokens"]},{"id":"hook","g":"ai","word":"Āķis","text":"Neliela komanda, kas automātiski izpildās noteiktā brīdī, piemēram, AI sesijas sākumā, lai komanda saņemtu tavus komentārus.","also":["hook","hooks","āķi","āķa","āķu"]},{"id":"ai","g":"ai","word":"Mākslīgais intelekts (MI, AI)","text":"Datorsistēmas, kas dara lietas, kurām parasti šķiet vajadzīgs cilvēks, piemēram, raksta, atbild uz jautājumiem vai atpazīst attēlus.","also":["AI","MI","mākslīgais intelekts","mākslīgā intelekta","mākslīgo intelektu","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Mašīnmācīšanās (ML)","text":"Veids, kā dators mācās likumsakarības no daudziem piemēriem, nevis saņem precīzus noteikumus.","also":["mašīnmācīšanās","machine learning"]},{"id":"model","g":"ai","word":"Modelis","text":"AI sistēmas apmācītās „smadzenes”, kas izveidotas, mācoties no milzīga piemēru skaita. Modeļiem atšķiras prasmes, ātrums un cena.","also":["modeļi","modeļa","modeli","modelim","AI modelis","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Lielais valodas modelis (LLM)","text":"AI modelis, kas apmācīts ar milzīgu teksta apjomu, lai spētu lasīt un rakstīt valodu.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Ģeneratīvais AI","text":"AI, kas rada jaunas lietas, piemēram, tekstu, attēlus vai kodu, nevis tikai tās šķiro vai atpazīst.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Tērzēšanas robots","text":"Programma, ar ko sarunājies ikdienas valodā, rakstot vai runājot.","also":["tērzēšanas roboti","chatbots"]},{"id":"prompt","g":"ai","word":"Uzvedne","text":"Tas, ko dod AI: jautājums vai norādījumi kopā ar pievienoto materiālu. Skaidrākas uzvednes parasti dod labākas atbildes.","also":["uzvednes","uzvedni","uzvedņu","prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Uzvedņu veidošana","text":"Prasme rakstīt uzvednes, kas sniedz uzticamus un noderīgus rezultātus.","also":["uzvedņu rakstīšana"]},{"id":"sysprompt","g":"ai","word":"Sistēmas uzvedne","text":"Fona norādījumi, ko AI saņem pirms sarunas un kas nosaka tā lomu un noteikumus. Tiem ir lielāks svars nekā tavam ierakstītajam.","also":["sistēmas uzvednes","sistēmas norādījumi","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Konteksts","text":"Viss, ko AI darba laikā redz: norādījumi, tavi ziņojumi, izlasītie faili un iepriekšējās atbildes.","noTip":1},{"id":"ctxwin","g":"ai","word":"Konteksta logs","text":"Cik daudz AI spēj vienlaikus paturēt prātā, mērot tokenos. Pārsniedzot robežu, vecākās daļas atmet vai apkopo.","also":["konteksta logi","context windows"]},{"id":"session","g":"ai","word":"Sesija","text":"Viena darba saruna ar AI no sākuma līdz beigām. Jauna sesija sākas ar svaigu atmiņu.","also":["sesijas","sesiju","sesijā","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Atmiņa","text":"Piezīmes, ko AI saglabā starp sesijām, lai atcerētos tavas izvēles un agrākos lēmumus.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinācija","text":"Kad AI pārliecinoši pasaka ko izdomātu vai nepareizu. Svarīgus faktus pārbaudi.","also":["halucinācijas","halucināciju","halucinē","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Apmācība","text":"Modeļa mācīšana ar milzīgu piemēru skaitu, pirms to sāk izmantot.","also":["apmācīts","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Apmācības dati","text":"Piemēri, no kuriem modelis mācījās. Tā zināšanas beidzas ar šo datu savākšanas laiku.","also":["apmācības kopa","training set"]},{"id":"cutoff","g":"ai","word":"Zināšanu robeždatums","text":"Datums, ar kuru beidzas AI iebūvētās zināšanas. Par vēlāko tas uzzina tikai tad, ja to sameklē.","also":["apmācības robeždatums","training cutoff"]},{"id":"finetune","g":"ai","word":"Papildu pielāgošanas apmācība","text":"Esoša modeļa papildu apmācība ar taviem piemēriem, lai tas labāk paveiktu noteiktu darbu.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Secināšana","text":"AI modeļa izmantošana atbildes sniegšanai pretstatā tā apmācībai.","also":["modeļa secināšana","model inference"]},{"id":"tooluse","g":"ai","word":"Rīku izmantošana","text":"AI spēja ne tikai runāt, bet arī darboties: palaist komandas, lasīt failus vai meklēt tīmeklī ar lietotnes piešķirtajiem rīkiem.","also":["rīku izsaukšana","rīka izsaukums","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Apakšaģents","text":"AI palīgs, kam galvenais AI uztic mazāku darbu un no kura saņem rezultātu.","also":["apakšaģenti","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Vairāku aģentu sistēma","text":"Vairāki AI kopā veic vienu darbu, katrs savu daļu, gluži kā neliela komanda.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Patstāvība","text":"Cik daudz AI drīkst izdarīt pats, pirms jājautā cilvēkam.","also":["autonoms","autonomous"]},{"id":"hitl","g":"ai","word":"Cilvēka iesaiste","text":"Cilvēks svarīgos brīžos pārbauda vai apstiprina AI darbības. AI-gile tas esi tu.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Drošības robežas","text":"Ierobežojumi un pārbaudes AI drošai darbībai, piemēram, apstiprinājums pirms ieviešanas. Tie mazina kļūdu risku, bet tās neizslēdz.","also":["aizsargmehānisms","guardrail"]},{"id":"rag","g":"ai","word":"Ar izguvi papildināta ģenerēšana (RAG)","text":"AI pirms atbildēšanas meklē tavos dokumentos, lai atbildes balstītos tavos faktos.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Vektorizēts attēlojums (embedding)","text":"Teksta pārvēršana skaitļu sarakstā, kas raksturo tā nozīmi, lai dators varētu atrast līdzīgas nozīmes lietas.","also":["vektorizēti attēlojumi","embeddings"]},{"id":"vectordb","g":"ai","word":"Vektoru datubāze","text":"Datubāze, kas meklē nozīmi raksturojošos skaitļu sarakstos, lai atrastu līdzīga satura materiālu.","also":["vektoru datubāzes","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Kopīgs veids, kā AI lietotnēm pieslēgt rīkus un datu avotus, lai AI tos varētu izmantot.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatūra","text":"Iestatījums, kas nosaka AI atbilžu drosmīgumu: zema vērtība dod vienmērīgākas, paredzamākas atbildes, augsta — dažādākas. Neviena negarantē pareizību.","also":["modeļa temperatūra","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodāls","text":"Spēj strādāt ar vairāku veidu informāciju, piemēram, tekstu, attēliem un skaņu.","also":["vairākmodāls","multi-modal"]},{"id":"evals","g":"ai","word":"Novērtēšana (eval)","text":"Plānots tests, cik labi AI tiek galā ar izvēlētiem piemēriem, lai salīdzinātu modeļus vai uzvednes.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Neobjektivitāte","text":"Kad AI vai cilvēks netaisnīgi nosliecas vienā virzienā, bieži iemācītā dēļ.","also":["aizspriedumains","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Atbildīgs AI","text":"Godīga, droša un atklāta AI izmantošana, cilvēkiem saglabājot atbildību par rezultātiem.","also":["ētisks AI","ethical AI"]},{"id":"injection","g":"ai","word":"Uzvedņu injekcija","text":"Paņēmiens, kur tīmekļa lapā vai failā paslēpti norādījumi mēģina likt AI darīt to, ko lietotājs nav prasījis.","also":["uzvedņu injekcijas","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Pieprasījumu biežuma ierobežojums","text":"Robeža, cik pieprasījumu noteiktā laikā drīksti nosūtīt pakalpojumam. To pārsniedzot, jāgaida.","also":["biežuma ierobežojumi","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Lietojuma ierobežojums","text":"Cik daudz AI darba plāns atļauj noteiktā laikā; pēc tam darbs apstājas vai maksā vairāk.","also":["lietojuma ierobežojumi","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Programmatūras veidošana, galvenokārt aprakstot AI vēlamo un ļaujot tam uzrakstīt kodu.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budžets","text":"Naudas summa, kas atvēlēta kādam mērķim.","also":["budžeti","budžeta","budžetu","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Izmaksu aplēse","text":"Pamatots minējums par izmaksām pirms darba sākšanas.","also":["izmaksu aplēses","cost estimates"]},{"id":"roi","g":"money","word":"Ieguldījumu atdeve (ROI)","text":"Tas, ko iegūsti salīdzinājumā ar ieguldīto. Ja atdeve ir pozitīva, ieguldījums atmaksājās.","also":["ROI"]},{"id":"tco","g":"money","word":"Kopējās īpašuma izmaksas (TCO)","text":"Visas patiesās izmaksas visā dzīves laikā, ne tikai pirkuma cena: darbināšana, atbalsts, jaunināšana un beigās izbeigšana.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx un OpEx","text":"CapEx ir sākotnēji tēriņi lietām, ko paturi; OpEx ir regulārie izdevumi, piemēram, ikmēneša rēķini.","also":["CapEx","OpEx","kapitālizdevumi","darbības izdevumi","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonements","text":"Regulāra maksa, parasti katru mēnesi vai gadu, lai turpinātu kaut ko izmantot.","also":["abonementi","abonementa","abonementu","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Programmatūra kā pakalpojums (SaaS)","text":"Programmatūra, ko lieto tiešsaistē par abonēšanas maksu, kamēr tās veidotājs to tavā vietā uztur.","also":["SaaS"]},{"id":"payg","g":"money","word":"Maksa pēc lietojuma","text":"Maksā tikai par izmantoto, piemēram, mākoņdatošanu vai AI tokeniem.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Pārsniegums","text":"Lietojums virs plānā iekļautā apjoma, kas var maksāt papildus.","also":["pārsnieguma maksa","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Izmaksu brīdinājums","text":"Ziņojums, kad tēriņi vai lietojums sasniedz tevis izvēlētu līmeni. Tas brīdina, bet ne vienmēr aptur turpmākas izmaksas.","also":["izmaksu brīdinājumi","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Bezmaksas līmenis","text":"Maksas pakalpojuma bezmaksas līmenis ar ierobežojumiem. Noder sākumam.","also":["bezmaksas plāns","free plan"]},{"id":"pricing","g":"money","word":"Cenu plāns","text":"Dažādi pakalpojuma piedāvātie komplekti, katrs ar savu cenu un ierobežojumiem.","also":["cenu plāni","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"Noteikumi, kā drīksti izmantot, kopēt, mainīt vai kopīgot cita veidoto, piemēram, programmatūru, fontus vai attēlus.","also":["licences","licenci","licenču","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Atvērtais pirmkods","text":"Programmatūra, kuras kodu ikviens var bez maksas lasīt, izmantot un bieži arī mainīt saskaņā ar licences noteikumiem.","also":["atvērtā pirmkoda programmatūra","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Atvērtā pirmkoda licence","text":"Noteikumi, kas nāk līdzi atvērtam pirmkodam. Daži, piemēram, MIT, ļauj gandrīz visu; citi, piemēram, GPL, prasa kopīgot arī tavas izmaiņas.","also":["atvērtā pirmkoda licences","MIT licence","open source licences","GPL"]},{"id":"proprietary","g":"money","word":"Īpašniekprogrammatūra","text":"Uzņēmumam piederoša programmatūra, ko nedrīkst brīvi kopēt vai mainīt. Pretstats atvērtajam pirmkodam.","also":["slēgta programmatūra","proprietary software"]},{"id":"copyright","g":"money","word":"Autortiesības","text":"Autora likumīgas tiesības kontrolēt sava darba kopijas, tostarp kodu un tekstus.","also":["autortiesību aizsargāts","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intelektuālais īpašums (IP)","text":"Idejas un darbi, ko likums uzskata par īpašumu, piemēram, kods, dizaini, nosaukumi un logotipi.","also":["intelektuālais īpašums","intellectual property"]},{"id":"tos","g":"money","word":"Pakalpojuma noteikumi","text":"Noteikumi, kuriem piekrīti, izmantojot pakalpojumu.","also":["lietošanas noteikumi","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Līgums","text":"Rakstiska divu pušu vienošanās, kuras izpildi aizsargā likums.","also":["līgumi","līguma","līgumu","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Darba apraksts (SOW)","text":"Dokuments, kas precīzi nosaka, kādu darbu paveiks, līdz kuram laikam un par kādu samaksu.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fiksēta cena","text":"Saskaņota cena par visu darbu neatkarīgi no tā ilguma.","also":["nemainīga cena","fixed-price"]},{"id":"tm","g":"money","word":"Laika un materiālu apmaksa","text":"Maksa par patiešām nostrādātajām stundām un izmantotajām lietām, nevis fiksēta cena.","also":["T&M"]},{"id":"invoice","g":"money","word":"Rēķins","text":"Maksājuma pieprasījums par paveiktu darbu vai piegādātām precēm.","also":["rēķini","rēķina","rēķinu","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Piesaistīšana piegādātājam","text":"Kad piegādātāja maiņa ir tik grūta vai dārga, ka no tā vairs nevar tikt vaļā.","also":["atkarība no piegādātāja","lock-in"]},{"id":"procurement","g":"money","word":"Iepirkums","text":"Piegādātāju izvēles un pirkšanas process."},{"id":"servicecredit","g":"money","word":"Pakalpojuma kompensācija","text":"Naudas atmaksa vai atlaide, ja piegādātājs neizpilda SLA.","also":["pakalpojuma kompensācijas","service credits"]}]}};
